WITH payload AS (SELECT $archive_payload$[{"id":"167ff4b3-1296-51ce-872d-cf2b4eed609e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -شرب املسكر وحيازته بقصد االستعمال -والية -عوارض األهلية -إذا وقع اجلنون قبل المحاكمة فإنه مينعها -تقرير طبي -صرف النظر","document_number":"34377717","case_number":"3293909","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/03/26","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -شرب املسكر وحيازته بقصد االستعمال -والية -عوارض األهلية -إذا وقع اجلنون قبل المحاكمة فإنه مينعها -تقرير طبي -صرف النظر","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34377717:‬تاريخه‪1432/03/26 :‬هـ‬\n                           ‫رقم الدعوى‪3293909:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34372253‬تاريخه‪1434/11/26 :‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪ -‬شــرب املســكر‬\n      ‫وحيازتــه بقصــد االســتعمال‪ -‬واليــة‪ -‬عــوارض األهليــة‪ -‬إذا وقــع‬\n      ‫اجلنــون قبــل احملاكمــة فإنــه مينعهــا‪ -‬تقريــر طبــي‪ -‬صــرف النظــر‬\n                                                              ‫عــن الدعــوى‪.‬‬\n\n\n\n      ‫‪-1‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬رفــع القلــم عــن ثــاث‪ ...‬ومنهــا‬\n                                                             ‫املجنــون حتــى يعقــل)‪.‬‬\n                                                         ‫‪ -2‬العقل مناط التكليف‪.‬‬\n                                ‫‪ -3‬إذا وقع اجلنون قبل احملاكمة فإنه مينعها‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه تتضمــن طلــب إثبــات بحيــازة‬\n      ‫احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه له‪ ،‬وإدانته بشــرب املســكر‬\n      ‫وحيازتــه لــه بقصــد االســتعمال‪ ،‬واحلكــم عليــه بحــد املســكر وبعقوبــة‬\n      ‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة‪ ،‬وحيــث إنــه مت تفتيــش ســيارة املدعــى عليــه بعــد االشــتباه‬\n      ‫بهــا فعثــر فيهــا علــى قطعــة مــن احلشــيش املخــدر‪ ،‬وأثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‪،‬‬\n\n‫‪37‬‬\n\f‫حضــر وليــه الشــرعي وقــرر أن أخــاه املدعــى عليــه تعــرض حلــادث أفقــده‬\n‫الذاكــرة‪ ،‬ومــن املقــرر شــرع ًا أن العقــل منــاط التكليــف‪ ،‬إذا وقــع‬\n‫اجلنــون قبــل احملاكمــة فإنــه مينعهــا بنــاء علــى مــا تقــدم قضــت احملكمــة‬\n‫بصــرف النظــر عــن دعــوى املدعــي العــام ضــد املدعــى عليــه‪ ،‬وأخلــت‬\n‫ســبيله مــن هــذه الدعــوى وأفهمــت املدعــي العــام بــأن لــه حــق إقامــة‬\n‫الدعــوى علــى املدعــى عليــه حــال زوال العــارض واكتمــال أهليتــه‪،‬‬\n‫قنــع ولــي املدعــى عليــه باحلكــم وعــارض عليــه املدعــي العــام‪ ،‬وقــررت‬\n                             ‫محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬رئيــس احملكمــة اجلزائيــة بحائــل‬\n‫القائــم بأعمــال املكتــب القضائــي الســابع وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا برقــم ‪ 3293909‬وتاريــخ ‪1432/03/26‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 32281069‬وتاريــخ ‪1432/03/24‬ه ـ ففــي يــوم األربعــاء املوافــق‬\n‫‪1434/11/26‬ه ـ افتتحــت اجللســة متــام الســاعة احلاديــة عشــرة والربــع‬\n‫وفيــه حضــر املدعــي العــام‪ .......‬وادعــى علــى‪ .......‬ســعودي بالســجل رقــم‬\n‫(‪ ).......‬قائــا يف حتريــر دعــواه عليــه حيــث أنــه عنــد الســاعة التاســعة‬\n‫مــن صبــاح يــوم االثنــن املوافــق ‪1432/1/28‬ه ـ مت اشــتباه فرقــة مــن‬\n‫مكافحــة املخــدرات مبحافظــة بقعــاء بســيارة مــن نــوع جيــب ( ‪ ) ...‬صنــع‬\n‫عــام ‪2007‬م حتمــل اللوحــة رقــم (‪ ).....‬بيجــي اللــون متوقفــة داخــل محطــة‬\n‫‪ .......‬مبحافظــة بقعــاء وبداخلهــا قائدهــا وعنــد طلــب أوراقــه الثبوتيــة‬\n‫بــدت عليــه عالمــات االرتبــاك وتنبعــث منــه رائحــة كريهــة وبســؤاله عــن‬\n‫رائحتــه أفــاد أنهــا رائحــة العــرق املســكر الــذي شــربه األمــر الــذي دعــا‬\n\n                                                                                     ‫‪38‬‬\n\f     ‫لتفتيشــه فلــم يعثــر معــه علــى أي محظــورات وتبــن أنــه املدعــى عليــه‬\n     ‫وكان مرافقــه قادمــا مــن متوينــات احملطــة وعنــد طلــب أوراق الثبوتيــة‬\n     ‫بــدت عليــه عالمــات االرتبــاك وتنبعــث منــه رائحــة كريهــة وبســؤاله‬\n     ‫عــن رائحتــه أفــاد أنهــا رائحــة العــرق املســكر الــذي شــربه ‪ ،‬وبتفتيشــه‬\n     ‫شــخصيا لــم يعثــر معــه علــى أي محظــورات واتضــح أنــه املواطــن‪.......‬‬\n     ‫وبتفتيــش الســيارة املذكــورة والعائــدة ملكيتهــا لشــقيق املدعــى عليــه‬\n     ‫عثــر علــى ( بكــت دخــان ) مبنتصــف الطبلــون وبداخلــه قطعــة ســوداء‬\n     ‫اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )3.400‬ثــاث‬\n     ‫جرامــات وأربعمائــة مليجــرام ‪ ،‬كمــا عثــر على قارورة ماء صحة ســعة (‬\n     ‫‪ )0.600‬ســتمائة مليجــرام بهــا أكثــر مــن النصف مــادة كريهة الرائحة‬\n     ‫يشــتبه أن تكــون مــن مــادة العــرق املســكر بجانــب ناقــل احلركــة جهــة‬\n     ‫الراكــب ( مت فــرز أوراق مســتقلة للمواطــن ‪ .......‬إلقامــة الدعــوة عليــه‬\n     ‫يف محــل إقامتــه ‪ ،‬كمــا فــرزت أوراق مســتقلة لقيــادة املدعــى عليــه‬\n     ‫الســيارة حتــت تأثيــر املســكر ملعاجلتهــا مــن قبــل جهــة االختصــاص )‬\n     ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم ( ‪ )131‬الصــادر مــن‬\n     ‫املركــز اإلقليمــي ملراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n     ‫بالقصيــم برقــم ‪/294‬م س ‪ )45/65/‬لعــام ‪1432‬ه ـ ‪ ،‬إيجابيــة العينــة‬\n     ‫املرســلة للقطعــة املضبوطــة ملــادة احلشــيش املخــدر وعينــة املــادة الســائلة‬\n     ‫للكحــول املســكر وباســتجوابه اعتــرف بشــربه للمســكر وبحيازتــه‬\n     ‫ملــا مت ضبطــه معــه قاصــدا مــن ذلــك التعاطــي وأنــه يتعاطــى احلبــوب‬\n     ‫احملظــورة منــذ ســنة ويشــرب املســكر منــذ خمــس ســنوات وأن مرافقــه‬\n     ‫‪ ،‬لــم يســتعمل املســكر الــذي ضبــط معــه وقــد أســفر التحقيــق معــه عــن‬\n     ‫اتهامــه بشــرب املســكر وحيازتــه بقصــد االســتعمال وحيــازة قطعــة مــن‬\n\n\n‫‪39‬‬\n\f‫احلشــيش املخــدر بلــغ وزنهــا (‪ )3.400‬ثــاث جرامــات وأربعمائة مليجرام‬\n‫بقصـد التعاطــي وت ـعــاطيــه ملــادة احلش ـيــش امل ـخــدر يف الســابق‪ .‬وحيث‬\n‫إن مــا أقــدم عليــه فعــل محــرم ومعاقــب عليه شــرع ًا ونظام ًا أطلـ ــب إثبات‬\n‫إدانته بـمـ ــا أسند إلي ــه واحلك ــم عليه بـح ــد املسـك ــر لشرب ــه وحيازت ــه‬\n‫بقصـ ــد االستعم ـ ــال واحل ـك ـ ــم عـ ــليه مبــا يلــي‪ .1 :‬الســجن‪ .2 .‬الـمـن ــع‬\n‫مــن الســفر وفقــا للمــواد ( ‪ )56،41‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ‪ ،‬وحيازتــه وتعاطيــه احلشــيش املخــدر وبــاهلل التوفيــق‬\n‫أ‪.‬هــ‪ ،‬هكــذا ادعــى ‪ ،‬ويف هــذه اجللســة حضــر‪ .......‬ســجل رقــم (‪،).......‬‬\n‫الولــي الشــرعي علــى املدعــى عليــه مبوجــب الصــك الصــادر مــن‬\n‫احملكمــة العامــة بحائــل برقــم ‪ 3236877‬وتاريخ‪1432/12/25‬هــ‪،‬‬\n‫وأقــر بقولــه‪ :‬أفيدكــم بــان أخــي تعــرض حلــادث بتاريــخ ‪1432/5/7‬هــ‪،‬‬\n‫حيــث ال يــزال مقعــد ًا ‪ ،‬وغيــر مــدرك للوعــي (شــلل رباعــي)‪ ،‬حيــث فقــد‬\n‫ذاكرتــه ‪ ،‬وأرفــق لكــم صــورة مــن التقريــر الطبــي الصــادر بحــق أخــي‬\n‫فجــرى االطــاع علــى التقريــر الطبــي الــذي أشــار إليــه الولــي وأرفــق‬\n‫ضمــن طيــات املعاملــة حيــث فيــه مــا مضمونــه‪ ( :‬االستشــارة النفســية‪:‬‬\n‫تعــرف حالــة املريــض بحالــة مــا بعــد اإلصابــة الرضخيــة للدمــاغ مــع خلــل‬\n‫حــاد يف اإلدراك وتغيــرات ســلوكية‪ .‬لقــد قيمــت املريــض عنــد تنوميــه‪،‬‬\n‫وقــد كان املريــض مييــل الــى القتــال ومصــاب بالهيــاج وعدائــي مــن‬\n‫حــن آلخــر‪ ،‬يعانــي املريــض مــن قصــور حــاد يف االدراك علــى جميــع‬\n‫النطاقــات‪ ،‬وغيــر قــادر علــى التخاطــب يف محادثــة هادفــة) وجــاء فيــه‬\n‫أيضـ ًا (والتشــخيص احلالــي ‪ -1‬حالــة مــا بعــد التعــرض إلصابــة دماغيــة‬\n‫مــع رضــوض نزفيــة متعــددة يف أبريــل ‪2011‬م‪.-2 .‬خلــل رباعــي (شــلل‬\n‫طفيــف) مصحوبــا برنــح‪3 .‬ـ نوبــات تشــنجية جزئيــة معقــدة ‪4‬ـ قصــور‬\n\n\n                                                                                        ‫‪40‬‬\n\f     ‫يف اإلدراك مــع تغيــرات ســلوكية ‪5‬ـ فقــدان عــام للقــدرة علــى الــكالم‬\n     ‫( حبســة تعبيريــة عامــة ) ‪ ،‬وقصــور يف النطــق إثــر اخلضــوع لعمليــة‬\n     ‫غــرس أنبــوب التنفــس يف الرقبــة ( فغــر الرغامــي )‪6.‬ـ عــدم القــدرة علــى‬\n     ‫التحكــم باإلخــراج ( البــول والبــراز ) ‪7‬ـ اعتمــاد كلــي علــى اآلخريــن‪.‬‬\n     ‫فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وبنــاء علــى مــا تقــدم مــن‬\n     ‫صــك الواليــة وبعــد االطــاع علــى التقريــر الطبــي ‪ ،‬وحيــث إن العقــل‬\n     ‫منــاط التكليــف ‪ ،‬واملدعــى عليــه يف هــذه احلالــة ال يعقــل وال يعــي‬\n     ‫الزمــان وال املــكان‪ ،‬ال يســتطيع اخلطــاب ‪ ،‬والــرد علــى الــكالم ‪،‬‬\n     ‫وهــذا قــد ذكــره بعــض أهــل العلــم أن اجلنــون إذا وقــع قبــل احملاكمــة‬\n     ‫فإنــه مينــع احملاكمــة ‪ ،‬قــال‪ :‬عبــد القــادر عــودة يف كتابــه ( التشــريع‬\n     ‫اجلنائــي اإلســامي) فقــرة ‪ ( 428‬إذا حــدث اجلنــون قبــل احلكــم‪ ،‬فإنــه‬\n     ‫ال مينــع احملاكمــة عنــد الشــافعة واحلنابلــة ‪ ،‬وحجتهــم أن التكليــف ال‬\n     ‫يشــترط إال وقــت ارتــكاب اجلرميــة ‪ ،‬أمــا املالكيــة ‪ ،‬واحلنفيــة فيرون أن‬\n     ‫اجلنــون قبــل احلكــم مينــع احملاكمــة ويوقفهــا حتــى يــزول اجلنــون ‪ ،‬ألن‬\n     ‫شــرط العقوبــة التكليــف ‪ ،‬ويتفــق القانــون املصــري والفرنســي مــع رأي‬\n     ‫املالكيــة واحلنفيــة‪ ،‬ولكــن علــة اإليقــاف عندهــم هــي عجــز املجنــون‬\n     ‫عــن الدفــاع عــن نفســه ‪ ،‬وهــذه العلــة ظاهــرة يف نــص املــادة [ ‪]247‬‬\n     ‫مــن قانــون حتقيــق اجلنايــات املصــري)‪ .‬أ‪.‬ه ـ بتصــرف‪ .‬وحيــث ذكــر أهــل‬\n     ‫العلــم أن أهليــة الوجــوب الناقصــة‪ :‬هــي صالحيــة اإلنســان ألن تثبــت لــه‬\n     ‫حقــوق دون أن تثبــت عليــه واجبــات‪ .‬وهــي خاصــة باجلنــن إلــى الــوالدة‪،‬‬\n     ‫ا الســتحقاق اإلرث‪ ،‬والوصيــة‪ ،‬والنســب‪ ،‬ونحــو ذلــك‪.‬‬      ‫وبهــا يكــون أهـ ً‬\n     ‫و العتــه‪ :‬وهــو اختــال يف عقــل اإلنســان بحيــث يختلــط كالمه‪ ،‬فيشــبه‬\n     ‫كالم العقــاء مــرة‪ ،‬وكالم املجانــن أخــرى‪ ،‬واالختــال يتفــاوت مــن‬\n\n\n‫‪41‬‬\n\f‫شــخص آلخــر‪ ،‬فالعتــه الــذي يبقــى معــه إدراك ومتييــز ‪ -‬ليــس كإدراك‬\n‫العقــاء ومتييزهــم‪ ،-‬فهــذا يلحــق بالصبــي املميــز‪ ،‬بحيــث تثبــت لــه‬\n‫أهليــة أداء ناقصــة‪ ،‬دون الكاملــة‪ .‬ينظــر يف هــذا ( تيســير التحريــر‬\n‫(‪ ،)372/2‬وكشــف األســرار (‪ ،)385-384/4‬وشــرح التلويــح‬\n‫(‪ ،)352/2‬وقواطــع األدلــة (‪ ،)388/2‬وعــوارض األهليــة‪ ،‬للجبــوري‬\n‫(ص‪ ،196‬ومــا بعدهــا)‪ ،‬وأصــول الفقــه‪ ،‬للزحيلــي (‪ ،)170/1‬وأصــول‬\n‫الفقــه‪ ،‬للبــري (ص‪.)295‬فاحلالــة هــذه إمــا ينطبــق علــى املدعــى عليــه‬\n‫أهليــة الوجــوب الناقصــة‪ ،‬أو يكــون غيــر مكلــف النتفــاء العقــل لديــه‪،‬‬\n‫وقــد قــال صلــى اهلل عليــه وســلم يف احلديــث الــذي رواه اإلمــام أحمــد عــن‬\n‫عائشــة رضــي اهلل عنهــا (رفــع القلــم عــن ثــاث‪ ...‬ومنهــم املجنــون حتــى‬\n‫يعقــل)‪ ،‬لذلــك كلــه وبنــاء علــى مــا تقــدم فقــد صرفــت النظر عــن دعوى‬\n‫املدعــي العــام ضــد املدعــى عليــه‪ ،‬وأخليــت ســبيله مــن هــذه الدعــوى‪،‬‬\n‫وبذلــك حكمــت‪ ،‬كمــا أفهمــت املدعــي العــام بــأن لــه حــق إقامــة‬\n‫الدعــوى علــى املدعــى عليــه حــال زوال العــارض واكتمــال أهليتــه‪،‬‬\n‫وبعرضــه علــى ولــي املدعــى عليــه قنــع بــه ‪ ،‬وبعرضــه علــى املدعــي العــام‬\n‫لــم يقنــع بــه وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة اعتراضيــة‬\n‫وعليــه جــرى التوقيــع‪ .‬مت قفــل اجللســة يف متــام الســاعة الثانيــة عشــرة مــن‬\n‫هــذا اليــوم األربعــاء املوافــق ‪1434/11/26‬ه ـ ‪ ،‬واهلل املوفــق وصلــى اهلل‬\n‫وســلم علــى نبينــا محمــد وآلــه وصحبــه أجمعــن‪ .‬احلمــد هلل وحــده وبعــد‬\n‫ويف هــذا اليــوم الثالثــاء املوافــق ‪1434/12/17‬ه ـ ‪ ،‬افتتحــت اجللســة يف‬\n‫متــام الســاعة الثامنــة وخمســة وأربعــون دقيقــة ‪ ،‬وفيهــا عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف بحائــل مرفقــا بهــا القــرار رقــم ‪34378029‬‬\n‫وتاريــخ ‪1434/12/3‬ه ـ املتضمــن (وبدراســة القــرار وصــورة ضبطــه‬\n\n\n                                                                                      ‫‪42‬‬\n\f     ‫وأوراق املعاملــة والالئحــة االعتراضيــة ومــا أجــاب بــه فضيلتــه علــى قــرار‬\n     ‫الدائــرة رقــم ‪ 34339248‬وتاريــخ ‪1434/10/25‬هــ‪ ،‬لوحــظ أن القضيــة‬\n     ‫أن هــذه القضيــة غيــر خاضعــة لالســتئناف بعــد اإليضــاح األخيــر‪ ،‬واهلل‬\n     ‫املوفــق) قاضــي اســتئناف‪( .......‬ختمــه وتوقيعــه) قاضــي اســتئناف ‪.......‬‬\n     ‫(ختمــه وتوقيعــه) رئيــس الدائــرة‪( .......‬ختمــه وتوقيعــه)‪ .‬وعليــه أنبــه‬\n     ‫أصحــاب الفضيلــة قضــاة محكمــة االســتئناف ـ وفقهــم اهلل لــكل‬\n     ‫خيــر ـ أنــه ال بــد مــن تدقيــق احلكــم‪ ،‬كونــه حكــم يف قضيــة جنائيــة‬\n     ‫مآلهــا التعزيــر‪ ،‬طبقــا للمــادة ( ‪ )193‬مــن نظــام اإلجــراءات اجلزائيــة‪،‬‬\n     ‫وقــررت إعــادة املعاملــة حملكمــة االســتئناف إلجــراء الزمهــا‪ ،‬واهلل‬\n     ‫املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                               ‫يف ‪1434/12/17‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n     ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة حائــل‬\n     ‫علــى املعاملــة الــواردة إلينــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n     ‫بحائــل برقــم ‪ 341924618‬وتاريــخ ‪1434/12/1‬هـ واملقيدة لدينا برقم‬\n     ‫‪ 341924618‬وتاريــخ ‪1434/12/2‬ه ـ املرفــق بهــا القــرار الشــرعي رقم‬\n     ‫‪ 34372253‬وتاريــخ ‪14343/11/26‬هــ‪ ،‬الصــادر مــن فضيلــة الشــيخ ‪....‬‬\n     ‫رئيــس احملكمــة اجلزائيــة بحائــل‪ ،‬اخلــاص بدعــوى املدعــي العــام ضــد‬\n     ‫املدعــى عليــه‪ .......‬ســعودي اجلنســية حامــل الســجل املدنــي رقــم (‪).......‬‬\n     ‫التهامــه بقضيــة حيــازة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه‬\n     ‫بصــرف النظــر عــن دعــوى املدعــي العــام علــى النحــو املفصــل فيــه‪،‬‬\n     ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‪ :‬جــرت املصادقــة علــى‬\n     ‫مــا حكــم بــه فضيلتــه بالقــرار املشــار إليــه مــع تنبيــه فضيلتــه أنــه‬\n\n\n‫‪43‬‬\n\f‫يوجــد خطــاء يف تاريــخ صــك الواليــة وتاريــخ وقــوع احلــادث علــى املدعــى‬\n‫عليــه وذلــك يف القــرار وضبطــه فــا بــد مــن تصحيحــه واهلل املوفــق ‪.‬‬\n                                      ‫وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n                                                                                  ‫‪44‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":37,"source_page_end":44,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a78cb2caddfef46c22510a352e1ccf44e05b82b72b8b025886e682d0b2507ca8","normalized_text_hash":"64b6f7a034ee429a9075cc46f8fcd62108f58d08eed958370ebeaa2705fe6fb3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p37-34377717"},{"id":"edaab4fb-5877-5dc6-b7af-6957acbfc1fa","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة وترويج وبيع وتعاطي احلشيش -إقرار بالتعاطي -إنكار الترويج -املتهم من أصحاب السوابق -تقرير كيميائي - قبض يف حالة تلبس -تشديد العقوبة -ثبوت إدانة -جلد وسجن -مصادرة ومنع من السفر.","document_number":"33123104","case_number":"3381218","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/02/22","year":"1434","subject":"مخدرات -حيازة وترويج وبيع وتعاطي احلشيش -إقرار بالتعاطي -إنكار الترويج -املتهم من أصحاب السوابق -تقرير كيميائي - قبض يف حالة تلبس -تشديد العقوبة -ثبوت إدانة -جلد وسجن -مصادرة ومنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33123104:‬تاريخه‪1433/02/22 :‬هـ‬\n                            ‫رقم الدعوى‪3381218:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                       ‫‪ 456‬تاريخه‪1433/07/14:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة وترويــج وبيــع وتعاطــي احلشــيش ‪ -‬إقــرار بالتعاطــي‬\n      ‫‪ -‬إنــكار الترويــج ‪ -‬املتهــم مــن أصحــاب الســوابق ‪ -‬تقريــر كيميائــي ‪-‬‬\n      ‫قبــض يف حالــة تلبــس ‪ -‬تشــديد العقوبــة ‪ -‬ثبــوت إدانــة ‪ -‬جلــد وســجن‬\n                                                  ‫‪ -‬مصــادرة ومنــع مــن الســفر‪.‬‬\n\n\n\n                                                                         ‫‪-1 .1‬حد املسكر‪.‬‬\n      ‫‪-2 .2‬الفقــرة (‪ )2‬مــن املــادة الثالثــة واملــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة‬\n      ‫(‪ )53‬واملــادة (‪ )56‬والفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة‬\n                                                    ‫املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n              ‫أقام املدعي العام دعواه ضد املدعى عليه طالب ًا احلكم عليه بـ‪:‬‬\n                                                    ‫‪ .1‬حد املسكر لتعاطيه احلشيش‪.‬‬\n      ‫‪ .2‬القتــل طبقــا للفقــرة اخلامســة مــن البنــد أو ًال مــن املــادة ‪ 37‬مــن نظــام‬\n                                                          ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n                                                                       ‫‪ .3‬مصادرة جواله‪.‬‬\n      ‫وذلــك بعــد القبــض عليــه متلبس ـ ًا بترويــج قطعــة مــن احلشــيش وحيازتــه‬\n      ‫ألخــرى وقــد أنكــر املدعــى عليــه االجتــار وأقــر بالتعاطــي‪ ،‬واطلعــت‬\n\n‫‪45‬‬\n\f‫احملكمــة علــى ســوابق املدعــى عليــه وأنــه قــد حكــم عليــه يف قضايــا‬\n‫اجتــار وســرقة ســيارات واعتــداء وضــرب واســتعمال مخــدرات واطلعــت‬\n‫علــى محاضــر الضبــط وقــررت حبســه ســبع ســنوات وجلــده ســبعمائة‬\n‫جلــده وإقامــة حــد املســكر ومصــادرة جوالــه ومنعــه مــن الســفر مــدة‬\n‫مماثلــة ملــدة احلبــس وارتضــى املدعــى عليــه احلكــم ورفضــه املدعــي‬\n‫العــام وجــرى إعادتــه للمحكمــة مــن محكمــة االســتئناف لقلــة العقوبــة‬\n‫وعليــه قــررت احملكمــة حبســه عشــر ســنوات وجلــده ألــف جلــدة ومنعــه‬\n‫مــن الســفر عشــر ســنوات واإلبقــاء علــى باقــي العقوبــات‪ ،‬وعليــه جــرى‬\n                                      ‫تصديقــه مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد لدينــا نحــن كل مــن ‪ ................‬مســاعد رئيــس‬\n‫احملكمــة العامــة بالدمــام ‪................................‬باحملكمــة العامــة‬\n‫ـاء علــى أوراق املعاملــة الــواردة لنــا مــن فضيلــة رئيــس‬      ‫بالدمــام بنـ ً‬\n‫احملكمــة العامــة بالدمــام برقــم ‪ ................‬يف ‪1433/02/01‬ه ـ‬\n‫واملقيــدة بهــذه احملكمــة برقــم‪................‬يف ‪1433/02/01‬ه ـ املتعلقــة‬\n‫بدعــوى املدعــي العــام ضــد ‪................‬بشــأن مخــدرات الصــادر بهــا‬\n‫ســابق ًا القــرار الشــرعي رقــم ‪/4/13‬ض يف ‪1431/06/25‬ه ـ واملنقــوض‬\n‫مبوجــب قــرار محكمــة االســتئناف باملنطقــة الشــرقية رقــم ‪...............‬‬\n‫يف ‪1432/12/18‬ه ـ عليــه فقــد فتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام ‪ ................‬وحضــر حلضــوره ‪................‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪................‬وقــرر املدعــي العــام يف دعــواه احملــررة‬\n‫ا اســم املتهــم ‪ ................. :‬اجلنــس ‪ :‬ذكــر ‪ .‬اجلنســية ‪ :‬ســعودي‬    ‫قائ ـ ً‬\n\n                                                                                        ‫‪46‬‬\n\f     ‫الديانــة ‪ :‬مســلم ‪ .‬اللغــة ‪ :‬العربيــة تاريــخ امليــاد ‪1391/08/14 :‬هــ‪.‬‬\n     ‫مــكان امليــاد‪ ..... :‬العمــر وقــت اجلرميــة ‪ . 40 :‬نــوع الهويــة ‪:‬الســجل‬\n     ‫املدنــي ‪ .‬رقــم الهويــة‪................ :‬تاريــخ اإلصدار‪1407/03/29:‬هــ‪ .‬جهــة‬\n     ‫اإلصــدار‪ :‬أحــوال القطيــف ‪ .‬املهنــة ‪:‬متســبب احلالــة االجتماعيــة‪ :‬أعــزب‪.‬‬\n     ‫مــكان اإلقامــة ‪ .......... :‬الشــارع‪ . ... :‬رقــم املنــزل ‪ :‬ال يوجــد‪ .‬هاتــف‬\n     ‫املنــزل ‪ :‬ال يوجــد ‪ .‬الهاتــف احملمــول‪ .................:‬جهــة اإليقــاف‪ :‬شــعبة‬\n     ‫إصالحيــة الدمــام ‪ .‬تاريــخ القبــض ‪ . 1430/11/19 :‬حالــة املتهــم‪:‬‬\n     ‫موقــوف ‪ .‬تاريــخ اإلفــراج‪ :‬ال يوجــد االتهــام ‪ :‬بيــع املــواد املخــدرة وحيــازة‬\n     ‫مــواد مخــدرة بقصــد التعاطــي أو االســتعمال ‪ .‬الســوابق رقــم احلكــم‪:‬‬\n     ‫‪ .................‬تاريخــه ‪409/06/05:‬ه ـ ‪ .‬مصــدره ‪ :‬مســتعجلة الدمــام‪.‬‬\n     ‫اجلرميــة ‪ :‬اعتــداء ‪ ،‬أحــداث جــروح أو كدمــات ومــا دونهــا ‪ .‬رقــم احلكــم‪:‬‬\n     ‫‪ . 21/2‬تاريخــه ‪1422/02/04 :‬ه ـ ‪ .‬مصــدره ‪ :‬الدمــام ‪.‬اجلرميــة ‪ :‬شــرب‬\n     ‫املســكرات‪ ،‬ســرقة ســيارات ‪ ،‬ســرقة لوحــة ســيارة ‪ .‬رقــم احلكــم ‪:‬‬\n     ‫‪ . 94/2‬تاريخــه ‪1423/05/28 :‬ه ـ ‪ .‬مصــدره ‪ :‬الدمــام ‪ .‬اجلرميــة ‪:‬شــرب‬\n     ‫املســكرات‪ ،‬أطــاق نــار‪ ،‬حيــازة ســاح بــدون ترخيــص‪ ،‬حيــازة‬\n     ‫الذخيــرة ‪ .‬رقــم احلكــم‪ . 151/5‬تاريخــه ‪1423/08/23 :‬ه ـ ‪ .‬مصــدر‪:‬‬\n     ‫الدمــام‪ .‬اجلرميــة ‪:‬اعتــداء‪ ،‬اعتــداء ‪ -‬أحــداث جــروح أو كدمــات ومــا‬\n     ‫دونهــا ‪ .‬رقــم احلكــم‪ . 150‬تاريخــه ‪1425/08/28 :‬ه ـ ‪ .‬مصــدر‪ :‬الدمــام‪.‬‬\n     ‫اجلرميــة ‪:‬مخــدرات ‪ ،‬ترويــج املخــدرات ‪ .‬رقــم احلكــم‪ .162/1‬تاريخــه‪:‬‬\n     ‫‪1426/12/04‬ه ـ ‪ .‬مصــدره‪ :‬الدمــام ‪.‬اجلرميــة ‪:‬ســرقة ســيارات‪ .‬رقــم‬\n     ‫احلكــم‪/1/127‬م‪ . 27‬تاريخــه ‪1430/06/21 :‬هــ‪ .‬مصــدره‪ :‬القطيــف‬\n                                                        ‫اجلرميــة اســتعمال املخــدرات‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪ ..‬بصفتــي‬\n\n\n‫‪47‬‬\n\f‫مدعيـ ًا عامـ ًا بدائــرة االدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية أدعي‬\n‫علــى املذكــور أعــاه أنــه بتاريــخ ‪1430/11/19‬ه ـ مت القبــض علــى‬\n‫املتهــم أعــاه مــن قبــل مكافحــة املخــدرات بالدمــام بعــد ورود معلومــات‬\n‫ـاء عليــه مت أخــذ رقــم‬  ‫ســرية عــن قيامــه بترويــج احلشــيش املخــدر وبنـ ً‬\n‫جوالــه مــن املصــدر بعــد التنســيق مــع املصــدر بإفهــام املدعــى عليــه‬\n‫بوجــود احــد األشــخاص الذيــن يريــدون شــراء كميــة مــن احلشــيش‬\n‫املخــدر ومت االتصــال عليــه مــن قبــل احــد اعضــاء الفرقــة علــى جوالــه‬\n‫رقــم (‪ )................‬وأنــه الشــخص الــذي يريــد شــراء كميــة مــن احلشــيش‬\n‫املخــدر وأنــه مرســول عليــه مــن قبــل املصــدر فطلــب منــه االتصــال عليــه‬\n‫عنــد وصولــه وعليــه مت تزويــد عضــو الفرقــة املكلفــن بــدور املشــتري‬\n‫باملبلــغ احلكومــي املرقــم وعقــب نصــف ســاعة تقريب ـ ًا ورد اتصــال مــن‬\n‫جــوال املدعــى عليــه يســأله فيــه عــن وصولــه فقــال لــه نعــم أنــا يف الدمــام‬\n‫فطلــب منــه املدعــى عليــه احلضــور إليــه يف شــارع ‪ .........‬عنــد محطــة‬\n‫(‪ ).........‬وعنــد الوصــول إلــى هنــاك شــوهد املدعــى عليــه يحضــر اليهــم‬\n‫ا علــى اقدامــه وقــام بتســليم قطعــة ســوداء اللــون بلــغ وزنهــا (‪)5.8‬‬ ‫مترجـ ً‬\n‫خمســة جــرام وثمــان أعشــار اجلــرام مــن احلشــيش املخــدر اثبــت التقريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ ).........‬وتاريــخ ‪1430/12/1‬ه ـ إيجابيــة‬\n‫عينتهــا ملــادة احلشــيش املخــدر وقــام باســتالم املبلــغ احلكومــي املرقــم‬\n‫ومــن ثــم أعطيــت اإلشــارة الدالــة علــى عمليــة الترويــج واالســتالم‬\n‫والتســليم فتــم مداهمتــه والقبــض عليــه وقــام برمــي املبلــغ احلكومــي‬\n‫املرقــم عنــد أقدامــه وبتفتيشــه شــخصيا ضبــط علــى علبــة ســوداء‬\n‫(مغناطيــس) عثــر بداخلهــا علــى قطعــة ســوداء اللــون بلــغ وزنهــا (‪)2‬‬\n‫جرامــن اثبــت التقريــر الكيمــاوي الشــرعي املنــوه عنــه إيجابيتهــا ملــادة‬\n\n\n                                                                                        ‫‪48‬‬\n\f     ‫احلشــيش املخــدر ومبناقشــته اعتــرف أمــام الفرقــة القابضــة بقيامــه‬\n     ‫بعمليــة الترويــج ‪ ،‬وبســماع أقــوال املتهــم األوليــة أقــر بصحــة واقعــه‬\n     ‫القبــض عليــه وبقيامــه الترويــج للحشــيش املخــدر مقابــل مبلــغ مائتــا‬\n     ‫ريــال وأقــر بتعاطيــه للحشــيش املخــدر واحلبــوب املنبهــة واحملضــورة ‪،‬‬\n     ‫وباســتجواب املتهــم ‪ .......‬اقــر بصحــة واقعــة القبــض وبيعــه املخــدر وأفــاد‬\n     ‫أنــه اتصــل عليــه شــخص يعرفــه وذكــر أنــه ســوف يرســل إليــه شــخص‬\n     ‫مــن طرفــه لشــراء قطعــة مــن احلشــيش املخــدر فوافــق علــى ذلــك لوجــود‬\n     ‫قطعــة مــن احلشــيش املخــدر موجــود لديــه وعنــد مقابلتــه لهــذا الشــخص‬\n     ‫وبعــد تســليمه قطعــة احلشــيش املخــدر مت القبــض عليــه وأضــاف بــأن‬\n     ‫الرقــم (‪ )................‬يعــود لــه وأفــاد أنــه قــام برمــي املبلــغ احلكومــي خلوفه‬\n     ‫مــن رجــال املكافحــة واقــر بتعاطيــه للحشــيش املخــدر وبنــاء علــى مــا‬\n     ‫ذكــر اقــرر اتهــام ‪ ................‬باآلتــي ‪ -1 :‬ترويجــه كميــة احلشــيش‬\n     ‫املخــدر البالــغ وزنهــا ( ‪ ) 5.8‬خمســة جرامــات و ثمانيــة أعشــار اجلــرام‬\n     ‫بالبيــع ‪ -2‬بحيــازة مــا وزنــه ( ‪ ) 2‬جرامــن مــن احلشــيش املخــدر بقصــد‬\n     ‫التعاطــي ‪ -3‬بتعاطيــه للحشــيش املخــدر واحلبــوب املنبهــة واحملظــورة‬\n     ‫وذلــك لألدلــة و القرائــن التاليــة ‪ -1 :‬مــا ورد يف أقــوال املتهــم املنــوه عنهــا‬\n     ‫اللفــة رقــم (‪ -2 ) 14-12‬محضــر القبــض و االنتقــال و التفتيــش املعــد‬\n     ‫مــن الفرقــة القابضــة علــى دفتــر التحقيــق على اللفة رقــم (‪ -3 )2‬التقرير‬\n     ‫الكيمــاوي الشــرعي املنــوه عنــه اللفــة رقــم (‪ )16 - 15‬وبالبحــث عــن‬\n     ‫ســوابقه تبــن وجــود ســوابق لــه مــن ضمنهــا ســابقة ترويــج صــدر بحقهــا‬\n     ‫احلكــم رقــم (‪ )150‬وتاريــخ ‪1425/8/28‬ه ـ مــن احملكمــة اجلزئيــة‬\n     ‫بالدمــام‪ .‬وصــدر قــرار جلنــة إدارة الهيئــة رقــم (‪ ).........‬باملوافقــة علــى مــا‬\n     ‫انتهــى إليــه قــرار االتهــام ‪.‬و حيــث أن مــا أقــدم عليــه املدعــى عليــه وهــو‬\n\n\n‫‪49‬‬\n\f‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب‬\n‫إثبــات قيــام املدعــى عليــه ‪ ....‬بيــع و حيــازة احلشــيش املخــدر بقصــد‬\n‫االجتــار وفق ـ ًا للفقــرة رقــم ( ‪ ) 2‬مــن املــادة رقــم ( ‪ ) 3‬واملــادة رقــم ( ‪) 3‬‬\n‫مــن نظــام اإلجــراءات اجلزائيــة و املــادة رقــم ( ‪ ) 64‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة و احلكــم عليــه مبــا يلي‪ -1 :‬بحد املســكر‬\n‫لقــاء اعترافــه بتعاطــي احلشــيش املخــدر ‪-2‬بعقوبــة القتــل املنصــوص‬\n‫عليهــا يف الفقــرة رقــم ( ‪ ) 5‬مــن البنــد أو ًال مــن املــادة ( ‪ ) 37‬مــن النظــام‬\n‫‪ -3.‬مبصــادرة جوالــه الــذي يحمــل الرقــم املصنعــي رقــم ( ‪)................‬‬\n‫وفقـ ًا للفقــرة ( ‪ ) 1‬مــن املــادة ( ‪ ) 53‬مــن النظــام وعــدم صــرف الشــريحة‬\n‫لــه وفقـ ًا لتعميــم وزيــر الداخليــة رقــم ( ‪ ) 9798‬وتاريــخ ‪1428/2/10‬ه ـ‬\n‫وبــاهلل التوفيــق هكــذا ادعــى وبســؤال املدعــى عليــه أجــاب بقولــه ‪ :‬مــا‬\n‫ذكــره املدعــي العــام مــن أنــه مت القبــض علــي وبحوزتــي جرامــن (‪2‬جم)‬\n‫مــن احلشــيش املخــدر وأننــي أتعاطــى احلشــيش املخــدر فهــذا صحيــح‬\n‫وأمــا مــا ذكــره املدعــي العــام مــن قيامــي بترويــج كميــة مــن احلشــيش‬\n‫املخــدر بلــغ وزنهــا خمســة جرامــات وثمانيــة أعشــار اجلــرام (‪5,8‬جــم) عــن‬\n‫طريــق البيــع فهــو غيــر صحيــح والصحيــح هــو أن زميلــي ‪................‬وهــو‬\n‫املصــدر قــد قابلنــي وســلمني قطعــة مــن احلشــيش املخــدر يبلــغ وزنهــا‬\n‫خمســة جرامــات وثمانيــة أعشــار اجلــرام (‪5,8‬جــم) وطلــب منــي تســليمها‬\n‫لشــخص يعرفــه وبعدهــا وردنــي اتصــال مــن أحــد األشــخاص علــى‬\n‫جوالــي الــوارد يف الدعــوى وطلــب مقابلتــي فقابلتــه علــى شــارع ‪.........‬‬\n‫وأخبرنــي أنــه مــن طــرف زميلــي ‪ ...‬فســلمته قطعــة احلشــيش التــي ســلمها‬\n‫لــي ‪ ................‬ولــم أســتلم مــن هــذا الشــخص أي مبلــغ مالــي علم ـ ًا أن‬\n‫القطعــة املضبوطــة بحوزتــي تخصنــي والســتعمالي الشــخصي وقــد‬\n\n\n                                                                                          ‫‪50‬‬\n\f     ‫حتصلــت عليهــا مــن زميلــي ‪ ...‬كمــا أننــي قــد تعاطيــت احلشــيش املخــدر‬\n     ‫قبــل القبــض علــي بيومــن كمــا أن الســوابق املنســوبة لــي يف دعــوى‬\n     ‫املدعــي العــام وعددهــا ســبع ســوابق فهــي صحيحــة ومنهــا ســابقة ترويــج‬\n     ‫مخــدرات هكــذا أجــاب فســألنا املدعــي العــام البينــة علــى دعــواه فقــال‬\n     ‫أن بينتــي هــي مــا تضمنتــه أوراق املعاملــة مــن أقــوال ومحاضــر وتقاريــر‬\n     ‫هكــذا قــرر وللحاجــة للرجــوع إلــى أوراق املعاملــة لالطــاع عليهــا‬\n     ‫ورصــد مــا يلــزم رصــده فقــد رفعــت اجللســة ويف جلســة ثانيــة جــرى تصفح‬\n     ‫ثبــت لدينــا اآلتــي ‪ :‬املرســل عبــارة عــن حــرز ظــرف حكومــي وجــد‬\n     ‫بداخلــه ‪ -1‬العينــة رقــم (‪ )30/1242‬وهــي عبــارة عــن كيــس بالســتيك‬\n     ‫شــفاف عــدمي اللــون بــه قطعــة بنيــة اللــون تــزن مبيــزان القســم صــايف‬\n     ‫(‪ )0,3‬ثالثــة بالعشــرة مــن اجلــرام ثبــت إيجابيهــا ملــادة احلشــيش املخــدر‬\n     ‫‪ -2‬العينــة رقــم (‪/1242‬أ) وهــي عبــارة عــن كيــس بالســتيك شــفاف‬\n     ‫عــدمي اللــون بــه قطعــة بنيــة اللــون تــزن مبيــزان القســم صــايف (‪ )0,3‬ثالثــة‬\n     ‫بالعشــرة مــن اجلــرام ثبــت إيجابيهــا ملــادة احلشــيش املخــدر ‪.‬أهــ‪ .‬كمــا‬\n     ‫وجدنــا إجابــة املدعــى عليــه يف القــرار الشــرعي رقــم ‪/4/13‬ض يف‬\n     ‫‪1431/06/25‬ه ـ املرفــق (لفــه ‪ )73‬الصــادر ســابق ًا يف هــذه القضيــة‬\n     ‫تتضمــن مــا نصــه ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه صحيــح حيــث‬\n     ‫أتصــل بــي شــخص وطلــب منــي حشــيش فطلبــت منــه احلضــور الســتالم‬\n     ‫احلشــيش وملــا حضــر قمــت بتســليمه كميــة احلشــيش املذكــورة‬\n     ‫بالدعــوى واســتلمت منــه املبلــغ وقــدره مائتــان وخمســون ريــال ومت‬\n     ‫القبــض علــي وبحوزتــي املبلــغ كمــا أنــه ضبــط بحوزتــي علــى قطعــة‬\n     ‫حشــيش بلــغ وزنهــا جرامــن والســابقة املذكــورة يف الدعــوى صحيحــة‬\n     ‫حيــث أن لــي ســبع ســوابق ومنهــا ســابقة ترويــج للمخــدرات ‪.‬أهــ‪ .‬كمــا‬\n\n\n‫‪51‬‬\n\f‫وجدنــا صــورة القــرار الشــرعي الصــادر مــن احملكمــة اجلزئيــة بالدمــام‬\n‫برقــم ‪150‬يف ‪1425/08/28‬ه ـ املرفــق ( لفــه ‪ ) 37-33‬يتضمــن احلكــم‬\n‫بتعزيــر املدعــى عليــه ‪.....‬ترويــج احلبــوب املنبهــة واحملظــورة بالســجن ســنة‬\n‫وجلــده مائتــي جلــده ولــم جنــد يف القــرار مــا يفيــد ثبــوت إدانــة املدعــى‬\n‫عليــه بترويــج املخــدرات صراح ـ ًة ثــم رفعــت اجللســة إلحضــار املدعــى‬\n‫عليــه لعــرض مــا مت تدوينــه عليــه ورصــد إفادتــه ويف جلســة ثالثــة حضــر‬\n‫الطرفــان كل مــن املدعــي العــام ‪ ................‬واملدعــى عليــه‪................‬‬\n‫وبعــرض مــا مت تدوينــه انفـ ًا علــى املدعــى عليــه قــال‪ :‬مــا ورد يف أقوالــي‬\n‫لــدى التحقيــق غيــر صحيــح ســوى مــا أقــررت بــه لديكــم وقــد صــدرت‬\n‫منــي تلــك األقــوال باإلكــراه مــن احملقــق وال بينــة لــدي علــى دعــواي‬\n‫اإلكــراه كمــا أن مــا ورد يف محضــر القبــض ومــا ورد يف إجابتــي أثنــاء‬\n‫نظــر الدعــوى لــدى اللجنــة الســابقة فهــو غيــر صحيــح وأمــا مــا ورد يف‬\n‫التقريــر الكيمــاوي فــا أعلــم عنــه شــيئ ًا وأمــا القــرار الشــرعي الصــادر‬\n‫مــن احملكمــة اجلزئيــة بالدمــام املتضمــن احلكــم بتعزيــري بالســجن‬\n‫واجللــد يف قضيــة مخــدرات فهــو صحيــح هكــذا قــرر ثــم رفعــت اجللســة‬\n‫للتأمــل ويف جلســة رابعــة حضــر الطرفــان كل مــن املدعــي العــام‬\n‫‪ ................‬واملدعــى عليــه ‪ ................‬فنظــر ًا ملتقــدم من الدعوى واإلجابة‬\n‫وحيــث صــادق املدعــى عليــه علــى حيازتــه لكميــة مــن احلشــيش املخــدر‬\n‫بلــغ وزنهــا (‪ 2‬جــرام) بقصــد التعاطــي وأنــه تعاطــى احلشــيش املخــدر‬\n‫كمــا صــادق علــى صحــة الســوابق املنســوبة إليــه يف دعــوى املدعــي‬\n‫العــام وأنكــر الترويــج وحيــث قــرر املدعــى العــام أن بينتــه هــي مــا‬\n‫تضمنتــه أوراق املعاملــة وملــا جــاء يف أقــوال املدعــى عليــه لــدى التحقيــق‬\n‫مــن إقــراره ببيــع قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا خمســة جرامــات‬\n\n\n                                                                                           ‫‪52‬‬\n\f     ‫وثمانيــة أعشــار اجلــرام (‪ 5,8‬جــم) علــى أحــد األشــخاص بقيمــة قدرهــا‬\n     ‫مائتــان وخمســون ريــال (‪ )250‬وملــا تضمنــه محضــر االنتقــال والقبــض‬\n     ‫والتفتيــش املــدون نصــه آنف ـ ًا وملــا ورد يف إجابــة املدعــى عليــه لــدى‬\n     ‫حــكام القضيــة ســابق ًا يف القــرار الشــرعي رقــم ‪ ................‬يف‬\n     ‫‪1431/06/25‬ه ـ واملــدون نصهــا آنفـ ًا وملــا تضمنــه التقريــر الكيمــاوي‬\n     ‫املشــار إليــه آنف ـ ًا وألن القــرار الشــرعي الصــادر مــن احملكمــة اجلزئيــة‬\n     ‫بالدمــام برقــم ‪ 150‬يف ‪ 1425/8/28‬لــم تضمــن ثبــوت إدانــة املدعــى‬\n     ‫عليــه بترويــج املخــدرات صراحــة لــذا فقــد ثبــت لدينــا إدانــة املدعــى عليــه‬\n     ‫بترويــج كميــة مــن احلشــيش املخــدر بلــغ وزنهــا خمســة جرامــات وثمانيــة‬\n     ‫أعشــار اجلــرام (‪ 5,8‬جــم) عــن طريــق البيــع بقصــد االجتــار للمــرة األولــى‬\n     ‫وفق ـ ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة وصرفنــا النظــر عــن طلــب املدعــي العــام إيقــاع عقوبــة‬\n     ‫القتــل علــى املدعــى عليــه وقررنــا تعزيــر املدعــى عليــه لقــاء ذلــك بســجنه‬\n     ‫ملــدة ســبع ســنوات اعتبــارا مــن تاريــخ إيقافــه يف هــذه القضيــة وجلــده‬\n     ‫ســبعمائة جلــده مفرقــة علــى دفعــات كل دفعــه خمســن جلــده وبــن‬\n     ‫كل دفعــه وأخــرى ثالثــون يوم ـ ًا ودفــع غرامــه ماليــة قدرهــا خمســة‬\n     ‫وعشــرون ألــف ريــال (‪ )25000‬وفق ـ ًا للمــادة (‪ )38‬مــن نظــام املخــدرات‬\n     ‫ومنعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة الســجن‬\n     ‫مــدة مماثلــة ملــدة عقوبــة الســجن احملكــوم بهــا عليــه وفق ـ ًا للفقــرة‬\n     ‫األولــى مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات كمــا قررنــا‬\n     ‫مصــادرة جوالــه الــذي يحمــل الرقــم املصنعــي (‪ )................‬الــوارد يف‬\n     ‫الدعــوى وفقـ ًا للفقــرة األولــى مــن املــادة (‪ )53‬مــن النظــام وعــدم صــرف‬\n     ‫الشــريحة لــه كمــا قررنــا إقامــة حــد املســكر علــى املدعــى عليــه لقــاء‬\n\n\n‫‪53‬‬\n\f‫تعاطيــه احلشــيش املخــدر وذلــك بجلــده ثمانــن جلــده دفعــه واحــده كمــا‬\n‫ثبــت لدينــا إدانــة املدعــى عليــه بحيــازة جرامــن (‪2‬جــم) مــن احلشــيش‬\n‫املخــدر بقصــد التعاطــي وعقوبتــه علــى ذلــك مشــمولة بعقوبــة الترويــج‬\n‫املذكــورة بعاليــة وفقــا للفقــرة األولــى مــن املــادة (‪ )62‬مــن النظــام ومبــا‬\n‫ذكــر حكمنــا وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n‫االعتــراض علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة وقــرر املدعــى عليــه‬\n‫القناعــة باحلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                ‫وسلم حرر يف ‪1433/03/07‬هـ‬\n‫ويف يوم األربعاء املوافق ‪1433/04/14‬هـ الســاعة ‪ 01: 45‬ظهر ًا فتحت‬\n‫اجللســة وقــد أنقضــت املــدة احملــددة للمدعــي العــام وقدرهــا ثالثــون يومـ ًا‬\n‫التــي بــدأت بتاريــخ اســتالمه لنســخة احلكــم يف ‪1433/03/14‬هـ إال أنه‬\n‫لــم يتقــدم باعتراضــه خاللهــا لــذا يســقط حقــه يف االعتــراض وســوف‬\n‫يتــم رفــع القــرار الشــرعي وصــورة ضبطــه وأوراق املعاملــة حملكمــة‬\n‫االســتئناف إلكمــال الــازم حســب التعليمــات أن شــاء اهلل تعالــى‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1433/04/14‬ه ـ‬\n‫ويف يــوم األربعــاء املوافــق ‪1433/09/13‬ه ـ الســاعة ‪ 11: 45‬ظهــر ًا‬\n‫فتحــت اجللســة وفيهــا حضــر الطرفــان كل مــن املدعــي العــام ‪................‬‬\n‫واملدعــى عليــه ‪ ................‬وقــد أعيــدت لنــا املعاملــة مــن فضيلــة الرئيــس‬\n‫علــى خطــاب فضيلــة رئيــس محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫رقــم ‪................‬يف ‪1433/07/21‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة‬\n‫قضــاة الدائــرة اجلزائيــة اخلماســية األولــى يف محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية رقــم ‪................‬يف ‪1433/07/14‬ه ـ نــص احلاجــة‬\n‫منــه قولهــم ‪ :‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n\n\n                                                                                         ‫‪54‬‬\n\f     ‫باألكثريــة أن مــا حكــم بــه أصحــاب الفضيلــة قليــل جــد ًا ألن املدعــى‬\n     ‫عليــه ممــن يتوجــه عليــه التشــديد يف العقوبــة اســتنادا للمــادة (‪ )38‬مــن‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ملالحظــة ذلــك ومــن ثــم‬\n     ‫إعــادة املعاملــة إلكمــال الزمهــا ‪ .‬أ ه ـ ‪ .‬وجنيــب أصحــاب الفضيلــة ‪،‬‬\n     ‫وفقهــم اهلل ‪ ،‬أنــه بإعــادة دراســة القضيــة وتأملهــا وألن ســابقة الترويــج‬\n     ‫بحــق املدعــى عليــه وأن لــم تثبــت صراحــة يف القــرار الشــرعي الصــادر‬\n     ‫مــن احملكمــة اجلزئيــة بالدمــام املشــار إليــه آنفـ ًا إال أنــه ورد فيــه شــهادة‬\n     ‫كل مــن ‪ .................. ،..............‬املعدلــن التعديــل الشــرعي والذيــن لــم‬\n     ‫يقــدح بهمــا املدعــى عليــه مــن إحضــار املدعــى عليــه للحبــوب احملظــورة‬\n     ‫بقصــد بيعهــا واجتماعــه باملصــدر ومداهمتهمــا أثنــاء العمليــة كمــا‬\n     ‫أنــه ورد يف تســبيب احلكــم يف القــرار الشــرعي الصــادر مــن احملكمــة‬\n     ‫اجلزئيــة بالدمــام مــا نصــه ‪ :‬ومبــا أن البينــة قــد شــهدت بعمليــة البيــع مــن‬\n     ‫املدعــى عليهمــا ‪.‬أهــ‪ .‬لــذا قررنــا زيــادة تعزيــر املدعــى عليــه‪................‬‬\n     ‫وذلــك بســجنه ملــدة ثالثــة ســنوات وجلــده ثالثمائــة جلــده مفرقــة علــى‬\n     ‫دفعــات حســبما ذكــر آنفـ ًا ليصبــح مجمــوع مــا حكمنا به بحــق املدعى‬\n     ‫عليــه مــن ســجن وجلــد هــو ســجنه ملــدة عشــر ســنوات اعتبــارا مــن تاريــخ‬\n     ‫إيقافــه يف هــذه القضيــة وجلــده ألــف جلــده مفرقــة علــى دفعــات كل‬\n     ‫دفعــه خمســن جلــده وبــن كل دفعــة وأخــرى ثالثــون يومـ ًا وبــه حكمنــا‬\n     ‫ـاق علــى حالــه وبعــرض احلكــم علــى‬         ‫وأمــا باقــي حكمنــا الســابق فبـ ٍ‬\n     ‫الطرفــن قــرر املدعــي العــام أنــه ال زال علــى اعتراضــه علــى احلكــم‬\n     ‫وقــرر املدعــى عليــه القناعــة باحلكــم وصلــى اهلل علــى نبينــا محمــد حــرر‬\n                                                                      ‫يف ‪1433/09/13‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n\n\n‫‪55‬‬\n\f‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام‬\n‫برقــم ‪ ................‬وتاريــخ ‪1433/9/19‬ه ـ واملقيــدة لــدى احملكمــة‬\n‫برقــم ‪................‬وتاريــخ ‪1433/10/8‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫ذو الرقــم ‪ ................‬والتاريــخ ‪1433/3/9‬ه ـ الصــادر مــن أصحــاب‬\n‫الفضيلــة القضــاة باحملكمة‪................‬اخلــاص بدعوى‪/‬املدعــي العــام‬\n‫ضــد‪................/‬يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم‬\n‫أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪ .‬وحيــث ســبق دراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n‫أصحــاب الفضيلــة علــى قرارنــا رقم‪................‬وتاريــخ ‪1433/7/14‬ه ـ‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪ 1434/1/5‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪56‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":45,"source_page_end":56,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3f933285964555781d2675e2a8e0fc390e3e58c1d6892109f850086ccdcf8b11","normalized_text_hash":"6051741e3a3ff4d5462a64149efc2dc49f51b3e921a29a71034f8db1c78e1eb0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p45-33123104"},{"id":"595342cc-4307-5910-8cc5-2e9dbcd146d8","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي والترويج وتعاطيها -إقرار -بينة غير موصلة -إدانة باحليازة بقصد التعاطي- عقوبة بحدها األعلى -توصية باإليداع يف مصحة لعاج اإلدمان.","document_number":"3426395","case_number":"3412332","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املصادقة على احلكم بعد اإلجراء األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/18","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي والترويج وتعاطيها -إقرار -بينة غير موصلة -إدانة باحليازة بقصد التعاطي- عقوبة بحدها األعلى -توصية باإليداع يف مصحة لعاج اإلدمان.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3426395:‬تاريخه‪1434/01/18 :‬هـ‬\n                           ‫رقم الدعوى‪3412332:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34226785‬تاريخه‪1434/05/29:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي والترويــج‬\n      ‫وتعاطيهــا‪ -‬إقــرار‪ -‬بينــة غيــر موصلة‪ -‬إدانة باحليــازة بقصد التعاطي‪-‬‬\n      ‫عقوبــة بحدهــا األعلــى‪ -‬توصيــة باإليــداع يف مصحــة لعــاج اإلدمــان‪.‬‬\n\n\n\n\n              ‫‪ -1‬املواد (‪ )213‬و (‪ )215‬و(‪ )219‬من نظام اإلجراءات اجلزائية‪.‬‬\n      ‫‪ -2‬الفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام‬\n                                         ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n      ‫بحيــازة حبــوب اإلمفيتامــن احملظــورة بقصــد التعاطــي والترويــج‬\n      ‫وتعاطيــه لهــا‪ ،‬واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة واملنــع‬\n      ‫مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة حيــث‬\n      ‫قبــض عليــه بعــد ورود معلومــات عــن امتهانــه الترويــج وبتفتيــش ســكنه‬\n      ‫عثــر فيــه علــى كميــة مــن احلبــوب احملظــورة مخبــأة بطريق ســرية وأثبت‬\n      ‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة لإلمفيتامــن‬\n      ‫وقــد أقــر أمــام احملكمــة بحيازتــه للحبــوب احملظــورة بقصــد التعاطــي‬\n      ‫وتعاطيــه لهــا وأنكــر قصــد الترويــج‪ -‬طلبــت احملكمــة مــن املدعــي‬\n\n‫‪57‬‬\n\f‫العــام تقــدمي بيناتــه وقــررت ســماع شــهادة شــهود محضــر القبــض فلــم‬\n‫جتــد فيهــا مــا يثبــت حيازتــه لهــا بقصــد الترويــج ألن املدعــى عليــه مــن‬\n‫أربــاب الســوابق‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه بتعاطــي احلبــوب‬\n‫احملظــورة وحيازتهــا بقصــد التعاطــي وعــدم ثبــوت قصــد الترويــج‬\n‫وقــررت جلــده ســبعني جلــدة دفعــة واحــدة وســجنه ملــدة ســنتني ومنعــه‬\n‫مــن الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬وعرضــه علــى جلنــة طبيــة فــإن‬\n‫ثبــت إدمانــه يعالــج وحتتســب مــدة العــاج مــن مــدة الســجن احملكــوم‬\n‫بهــا‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬قــررت‬\n‫محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم بعــد اإلجــراء‬\n                                                                         ‫األخيــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بتبــوك املكلــف برقــم ‪ 3412332‬وتاريــخ ‪ 1434/01/07‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 3457630‬وتاريــخ ‪ 1434/01/07‬ه ـ ففــي يوم‬\n‫الثالثــاء املوافــق‪ 1434/01/13‬ه ـ افتتحــت اجللســة الســاعة ‪10 :45‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ .......‬املكلــف باالدعــاء العــام مــن قبــل هيئــة‬\n‫التحقيــق واالدعــاء العــام مبنطقــة تبــوك مبوجــب اخلطــاب رقــم ‪13058‬‬\n‫بتاريــخ ‪ 1433/9/ 5‬هـ ـ وحضــر حلضــور املدعــى عليــه‪ .......‬ســعودي‬\n‫مبوجــب الســجل املدنــي رقــم‪ .......‬فأدعــى قائــا يف حتريــر انــه بتاريــخ‬\n‫‪1433/11/20‬ه ـ توافــرت معلومــات عــن املدعــى عليــه مــن أحــد‬\n‫مصادرهــا الســرية تفيــد بامتهانــه ترويــج احلبــوب احملظــورة ويقيم بشــقق‬\n\n                                                                                       ‫‪58‬‬\n\f     ‫عــزاب بشــارع الســجن العــام وباالنتقــال ومراقبــة املوقــع اتضــح بــأن‬\n     ‫املدعــى عليــه املذكــور يقيــم بشــقق بالشــقة رقــم (‪ )26‬ولوحــظ عليــه‬\n     ‫احلــذر الشــديد ومقابلتــه ألشــخاص أثنــاء فتــرة املســاء ويف متــام الســاعة‬\n     ‫(الثانيــة ) صباحـ ًا شــوهد املدعــى عليــه أثنــاء دخولــه للشــقق املذكــورة‬\n     ‫وبتفتيشــه لــم يعثــر بحوزتــه علــى ممنوعــات وعثــر بحوزتــه علــى محفظــة‬\n     ‫شــخصية بداخلهــا مفتــاح شــقة ومبناقشــته مشــافهة أنكــر أنــه يقيــم‬\n     ‫بالشــقق وبعدهــا مت الصعــود بــه للــدور اخلامــس ومت فتــح بــاب الشــقة‬\n     ‫باملفتــاح الــذي عثــر بحوزتــه وبتفتيــش الشــقة عثــر بأحــد الغــرف وحتــت‬\n     ‫أحــد أفيــاش الكهربــاء علــى كيــس نايلــون بداخلــه مــا عــدده (‪)286‬‬\n     ‫مائتــن وســت وثمانــن حبــة مــن حبــوب يشــتبه أن تكــون محظــورة‬\n     ‫مخبــأة بطريقــة ســرية فتــم القبــض عليــه جــرى إيقــاف املدعــى عليــه‬\n     ‫اســتناد ًا للفقــرة الرابعــة مــن القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n     ‫‪1428/7/9‬ه ـ باســتجواب املدعــى عليــه‪ .......‬اعتــرف بحيازتــه لعــدد‬\n     ‫(‪ )286‬مائتــن وســت وثمانــن حبــة مــن احلبــوب احملظــورة بقصــد‬\n     ‫التعاطــي وتعاطيــه لنوعهــا يف الســابق ‪ ،‬وذكــر أنه حصــل على الكمية‬\n     ‫املضبوطــة مــن محافظــة حقــل وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n     ‫رقــم( ‪ 3032‬م‪/‬م س ت) لعام‪1433‬ه ـ الصــادر مــن مركــز مراقبــة‬\n     ‫الســموم والكيميــاء الطبيــة الشــرعية بصحــة تبــوك‪ ،‬إيجابيــة العينــة‬\n     ‫املســتقطعة مــن الكميــة املضبوطــة لإلمفيتامــن املنبــه للجهــاز‬\n     ‫العصبــي‪ ،‬وهــو مــن املؤثــرات العقليــة اخلاضعــة للرقابــة واملنــوه عنــه‬\n     ‫باجلــدول الثانــي فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م ‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n     ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه املذكــور بحيازة‬\n\n\n‫‪59‬‬\n\f‫مــا عــدده (‪ )286‬مائتــان وســت وثمانــون حبــة مــن حبــوب اإلمفيتامــن‬\n‫املنبــه للجهــاز العصبــي احملظــورة بقصــد الترويــج والتعاطــي وتعاطيــه‬\n‫لنوعهــا يف الســابق وذلــك لألدلــة والقرائــن التاليــة‪ - :‬اعترافــه ـ املنــوه‬\n‫عنــه ـ واملــدون علــى اللفــات رقــم (‪ -2.)17-16-15‬محضــر التفتيــش‬\n‫والقبــض ـ املنــوه عنــه ـ واملــدون علــى الصفحــات رقــم (‪ )12-3-2‬مــن‬\n‫دفتــر االســتدالل املرفــق لفــه رقــم (‪ -3.)1‬التقريــر الكيمائــي الشــرعي‬\n‫واملرفــق باللفــة رقــم (‪ )21‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه‬\n‫املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا ومجــرم ومعاقــب عليــه‬\n‫نظامـ ًا ‪ ،‬اســتناد ًا للمــادة( الثالثــة) الفقــرة (الثانيــة) مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم ( م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب مــا يلي‪.1:‬إثبــات إدانتــه مبــا أســند إليــه‬\n‫‪.2‬احلكــم عليــه بالســجن واجللــد والغرامــة لقــاء مــا أســند إليــه ‪ ،‬اســتناد ًا‬\n‫للفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام املخــدرات املشــار إليــه‪ - 3.‬احلكــم‬\n‫مبنعــه مــن الســفر خــارج اململكــة بعــد انتهــاء محكوميتــه ‪ ،‬اســتناد ًا‬\n‫للمــادة (‪ )56‬الفقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة املشــار إليــه أعــاه‪ - - 4 .‬تشــديد العقوبــة عليــه اســتناد ًا لتعميــم‬\n‫صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر‬\n‫الداخليــة رقــم(‪ )93958/5/1‬وتاريــخ ‪1429/8/23‬ه ـ لكثــرة ســوابقه‬\n‫التــي لــم تردعــه عقوباتهــا وبعــرض دعــوى املدعــي العــام علــى املدعــى‬\n‫عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه مــن أن مــا مت‬\n‫ضبطــه بحوزتــي كان لغــرض الترويــج غيــر صحيــح والصحيــح أنــه متــت‬\n‫مداهمتــي عندمــا أردت دخــول العمــارة التــي بهــا شــقة زميلــي وكنــت‬\n‫ســاكن معــه ضيافــة فقــط وقامــوا بتفتيشــي ولــم يعثــروا معــي علــى أي‬\n\n\n                                                                                        ‫‪60‬‬\n\f     ‫ممنوعــات ثــم دخلــوا معــي للشــقة وفتشــوها ووجــدوا هــذه احلبــوب‬\n     ‫وعددهــا مائتــان وســت وثمانــون حبــة وهــي مــن احلبوب احملظــورة وعائدة‬\n     ‫لــي وقصــدي مــن حيازتهــا االســتعمال وليــس الترويــج هكــذا أجــاب‬\n     ‫وبعــرض مــا أجــاب بــه املدعــى عليــه علــى املدعــي العــام أجــاب بقولــه‬\n     ‫الصحيــح مــا جــاء يف الئحــة الدعــوى وبســؤال املدعــى العــام هــل لديــك‬\n     ‫بينــه علــى مــا أدعيــت بــه أجــاب بقولــه نعــم وأطلــب مهلــة إلحضــار هــا‬\n     ‫هكــذا أجــاب وبنــاء عليــه جــرى رفــع اجللســة حلــن إحضــار البينــة ‪ ،‬ويف‬\n     ‫جلســة أخــرى حضــر الطرفــان وجــرى ســؤال املدعــي العــام عــن البينــة‬\n     ‫التــي وعــد بإحضارهــا يف هــذه اجللســة فأجــاب بقولــه‪ :‬لقــد أحضــرت‬\n     ‫معــي للشــهادة كل مــن ‪ .......‬وأطلــب ســماع مــا لديهــم هكــذا أجــاب‬\n     ‫وحضــر يف هــذه اجللســة ‪ .......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n     ‫رقــم‪ .......‬املولــود يف عــام ‪ 1395‬هــت ويســكن يف مدينــة تبــوك يف‪.......‬‬\n     ‫وال تربطنــي باملدعــى عليــه أي عالقــة هكــذا أفــاد كمــا حضــر ‪.......‬‬\n     ‫ســعودي مبوجــب الهويــة الوطنيــة رقــم‪ .......‬املولــود يف عــام ‪ 1409‬ه ـ‬\n     ‫ويســكن يف مدينــة تبــوك حــي ‪ .......‬وال تربطــه باملدعــى عليــه أي عالقــة‬\n     ‫هكــذا أفــاد وبســؤال الشــاهد األول عمــا لديــه مــن شــهادة شــهد بقولــه‬\n     ‫أشــهد اهلل أنــه يف وقــت متأخــر مــن الليــل وردتنــا معلومــات عــن املدعــى‬\n     ‫عليــه أنــه يقــوم بترويــج احلبــوب احملظــورة وانتظرنا عند الســكن نراقب‬\n     ‫حتــى جــاء املدعــى عليــه وقبضــت أنــا وزمالئــي عليــه وبتفتيشــه لــم يعثــر‬\n     ‫علــى أي ممنوعــات وعثرنــا علــى مفتــاح للشــقة يضعــه يف محفظــة النقــود‬\n     ‫وســألناه عــن املفتــاح هــل هــو لشــقتك وأنكــر ذلــك وســألناه هل تســكن‬\n     ‫يف هــذه الشــقة وكانــت شــقة مفروشــة يف شــارع ‪ .......‬يف حــي ‪.......‬‬\n     ‫وأنكــر وذهبنــا للشــقة التــي جاءتنــا عنهــا إخباريــة وهــو معنــا وفتحنــا‬\n\n\n‫‪61‬‬\n\f‫البــاب بنفــس املفتــاح الــذي عثرنــا عليــه بحوزتــه وقمنــا بتفتيــش الشــقة‬\n‫ووجدنــا كميــة مــن احلبــوب احملظــورة وعددهــا مئتــان وســت وثمانــون‬\n‫حبــة مخبــأة بطريقــة ســرية داخــل أحــد األفيــاش وبســؤاله عنهــا أجــاب‬\n‫بقولــه أنهــا عائــدة لــي وبعدهــا ذهبنــا بــه لــإدارة ولــم أشــاهد املدعــى‬\n‫عليــه يقــوم بالترويــج ولــم يقــر بذلــك أمامــي هكــذا أشــهد‪ ،‬وجــرى‬\n‫ســؤال الشــاهد الثانــي ‪ .......‬عمــا لديــه مــن شــهادة فشــهد بقولــه‪ :‬أشــهد‬\n‫هلل تعالــى أنــه وردتنــا مــن مصادرنــا إخباريــة تفيــد أن املدعــى عليــه يقــوم‬\n‫بترويــج احلبــوب احملظــورة وتوجهنــا ملــكان ســكنه وكان ذلــك بعــد‬\n‫منتصــف الليــل وراقبنــاه ولــم جنــد معــه علــى ممنوعــات ووجدنــا مفتــاح‬\n‫يف احملفظــة التــي معــه وســألناه عنــه هــل هــو لشــقتك التــي يف العمــارة‬\n‫وكاتــب عبــارة عــن شــقه مفروشــة يف حــي ‪ .......‬بشــارع ‪ .......‬وتوجهنــا‬\n‫للشــقة التــي جاءتنــا اإلخباريــة عنهــا وهــو معنــا وفتحنــا الشــقة بنفــس‬\n‫املفتــاح الــذي ضبــط بحوزتــه وفتشــنا الشــقة ووجدنــا احلبــوب احملظــورة‬\n‫وعددهــا مئتــان وســت وثمانــون حبــة مفرقــه علــى كيســن كيــس‬\n‫مملــوء باحلبــوب والكيــس الثانــي فيــه ربــع وأنــا الــذي أخرجتهــا بنفســي‬\n‫مــن الفيــش وســألناه عنهــا فأفــاد بأنهــا عائــدة لــه ويقصــد منهــا‬\n‫االســتخدام وال أعلــم هــل املدعــى عليــه يقــوم بالترويــج أوال هكــذا‬\n‫شــهد وبعــرض الشــاهدين وشــهادتهم علــى املدعــى عليــه أجــاب بقولــه‬\n‫الشــهود ال أقــدح فيهــم وشــهادتهم كلهــا صحيحــة إال قولهــم أنــي مــروج‬\n‫فغيــر صحيــح وهــم أقــروا أنهــم لــم يشــاهدوني أقــوم بالترويــج ومــا‬\n‫ذكــروه يف باقــي شــهادتهم فصحيــح هكــذا أجــاب وبســؤال املدعــي‬\n‫العــام هــل لديــك زيــادة بينــه أجــاب بقولــه أكتفــي مبــا قدمــت وليــس‬\n‫لــدي غيرهــا هكــذا أجــاب وبســؤاله عــن املعدلــن للبينــه أجــاب بقولــه‪:‬‬\n\n\n                                                                                       ‫‪62‬‬\n\f     ‫أحضــرت لتعديــل الشــاهدين كال مــن ‪ .......‬و‪ .......‬هكــذا أجــاب‬\n     ‫وجــرى ســؤال املعدلــن عــن الشــاهدين فأجابــا بقولهمــا أن الشــاهدين‬\n     ‫مــن أهــل الصــدق والعدالــة نحســبهم واهلل حســيبهم هكــذا أجابــا‬\n     ‫والنتهــاء وقــت اجللســة جــرى رفعهــا ويف جلســة أخــرى حضــر الطرفــان‬\n     ‫وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬\n     ‫بحيازتــه احلبــوب احملظــورة وعددهــا مائتــان وثمــان وســتون حبــة بقصــد‬\n     ‫التعاطــي وتعاطيــه الســابق وأنكــر قيامــه بالترويــج ولــم يقــم املدعــي‬\n     ‫العــام البينــة املوصلــة علــى دعــواه حيــث لــم يشــد فيهمــا برؤيتــه للمدعــى‬\n     ‫عليــه يقــوم بالترويــج والبيــع وغايــة مــا يف شــاهدتهما هــو مــا أقــر بــه‬\n     ‫املدعــى عليــه حيــث أن الكميــة املضبوطــة أكثيــرة وخبــأت بطريقــة‬\n     ‫ســرية ووضعــت يف كيســن متفرقــن وهــذه قــد تعد قرينه علــى الترويج‬\n     ‫إال أنهــا تتالشــى وذلــك ملــا ظهــر لــي مــن حــال املتهــم حيــث ظهــر عليــه أنــه‬\n     ‫مدمــن علــى تنــاول املؤثــرات العقليــة ووضعــه صحــي متدهــور ويؤيــد‬\n     ‫هــذا مــا علــى املدعــى عليــه مــن ســوابق وهــي ثــاث ســوابق علــى تنــاول‬\n     ‫املؤثــرات العقليــة بخــاف غيرهــا وبنــاء علــى املــادة (‪ )41‬الفقــرة (‪)1‬‬\n     ‫واملــادة (‪ )56‬الفقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة ونظــرا للســوابق املســجلة علــى املدعــى عليــه مــن جنــس هــذه‬\n     ‫الدعــوى وحيــث أن إقــراره بتعاطــي احلبــوب احملظورة أمــر محرم ومجرم‬\n     ‫يوجــب التعزيــر لــذا ثبــت لــدي إدانــة املدعــى عليــه بحيازتــه مائتــن وثمان‬\n     ‫وســتني حبــة مــن احلبــوب احملظــورة بقصــد التعاطــي وتعاطيــه الســابق‬\n     ‫لهــا ولــم يثبــت لــدي إدانتــه حيازتــه ملــا تقــدم ذكــره من احلبــوب احملظورة‬\n     ‫بقصــد الترويــج وقــررت مــا يلــي‪ :‬تعزيــر املدعــى عليــه بجلــده ســبعون‬\n     ‫جلــده دفعــة واحــدة‪ .‬ثانيــا‪ :‬تعزيــر املدعــى عليــه بســجنه مــدة ســنتني‬\n\n\n‫‪63‬‬\n\f‫يحتســب منهــا مــدة إيقافــه علــى ذمــة هــذه القضيــة‪ .‬ثالثــا‪ :‬منــع املدعــى‬\n‫عليــه مــن الســفر خــارج اململكــة بعــد انتهــاء فتــرة محكوميتــه مــدة‬\n‫ســنتني وبذلــك حكمــت وكمــا أوصــى بعــرض املدعــى عليــه علــى جلنــة‬\n‫طبيــة للكشــف عليــه فــإن ثبــت إدمانــه يعالــج وحتتســب مــدة عالجــه‬\n‫مــن مــدة احلكــم بســجنه احملكــوم بهــا آنفــا وبعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم وأمــا املدعــي العــام فقــد‬\n‫قــرر اعتراضــه مكتفي ـ ًا مبــا جــاء يف أوراق املعاملــة عــن تقــدمي الئحــة‬\n‫اعتراضيــة ‪ ،‬وللبيــان حــرر يف ‪ 1434/01/28‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد ففــي يــوم‬\n‫األربعاءاملوافــق‪ 1434/04/10‬ه ـ افتتحــت اجللســة الســاعة احلادية عشــر‬\n‫والربــع صباحــا وفيهــا قــد وردت املعاملــة مــن محكمــة االســتئناف‬\n‫مبنطقــة تبــوك بخطــاب فضيلــة رئيســها رقــم ‪ 34354790‬وتاريــخ‬\n‫‪ 1434/3/15‬ه ـ واملقيــدة باحملكمــة برقــم ‪ 34354790‬وتاريــخ‬\n‫‪1434/3/18‬ه ـ واملشــفوع بهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة‬\n‫اجلزائيــة األولــى رقــم ‪ 3454878‬وتاريــخ ‪ 1434/3/3‬ه ـ واملتضمــن مــا‬\n‫نصــه بعــد املقدمــة ( وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫لوحــظ مــا يلــي‪ :‬اوالً‪ :‬أن ماحكــم بــه فضيلتــه مــن تعزيــر املدعــى عليــه‬\n‫قليــل نظــر ًا لتوجــه التهمــة القويــة لــه باحليــازة لقصــد الترويــج ملــا ذكــر‬\n‫فضيلتــه يف تســبيبه مــن كثــرة الكميــة وتقســيمها وإخفائهــا بتلــك‬\n‫الطريقــة وإنــكاره للســكن وإخفائــه ملفتــاح الشــقة جميــع هــذه القرائن‬\n‫جتعــل التهمــة قويــة ضــدة ولتعــدد ســوابقه وتنوعهــا وســوئها‪ .‬ثانيــا ‪:‬‬\n‫أوصــى فضيلتــه بعــرض املدعــى عليــه علــى جلنــة طبيــة للكشــف عليــه‬\n‫ا يف احلكــم لــكان أولــى ‪.‬ملالحظــة مــا‬      ‫وعالجــه ولــو جعــل ذلــك داخ ـ ً‬\n\n\n                                                                                         ‫‪64‬‬\n\f     ‫ذكــر وإكمــال الــازم وإحلــاق مــا يجريــه يف الضبــط وصورتــه والقــرار‬\n     ‫ومــن ثــم إعــادة املعاملــة‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n     ‫وصحبــه وســلم‪ .‬قاضــي اســتئناف‪ .......‬ختمــه وتوقيعــه‪ .‬قاضــي اســتئناف‬\n     ‫‪ .......‬وقــع األصــل ومجــاز‪ .‬رئيــس الدائــرة ختمــه وتوقيعــه وأجيــب‬\n     ‫أصحــاب الفضيلــة وفقهــم اهلل عــن املالحظــة األولــى بــأن املدعــى عليــه‬\n     ‫ظهــر عليــه ظهــورا جليــا اإلدمــان علــى تعاطــي املخــدرات بــل ظاهــر‬\n     ‫شــكله يــدل علــى أنــه مــن املتعاطــن لهــا بكثــرة أو مــن مــدة طويلــة‬\n     ‫ويــدل علــى هــذا أيضــا مــا علــى املدعــى عليــه مــن ســوابق مــن جنــس هــذه‬\n     ‫الدعــوى لــذا فــإن الكميــة املضبوطــة معــه ال تعتبــر كثيــرة بالنظــر إلــى‬\n     ‫حالــه كمــا أن قرينــة تقســيمها علــى كيســن ووضعهــا يف مخبــأ ســري‬\n     ‫ليســت بقرينــة قويــة ترتقــي لتوجيــه التهمــة لــه بالترويــج بــل أســلفت أنهــا‬\n     ‫تتالشــى مــع كونــه مدمــن وقــد يكــون تقســيمها ليــس منــه بــل مــن حــن‬\n     ‫مــا اشــترها فهــذه القرينــة تطــرق إليهــا االحتمــال وعليــه يبطــل بهــا‬\n     ‫االســتدالل ثــم إن املدعــي العــام لــم يقــدم بينــة علــى قصــد الترويــج ولــم‬\n     ‫يــدع بأنــه قبــض عليــه وهــو يقــوم بعمليــة الترويــج وغايــة مــا ذكــره أن‬\n     ‫الكميــة تعتبــر كميــة للترويــج ال للتعاطــي وهــذا األمــر منقــوض‬\n     ‫بعكســه فــا يســتقيم وقــد بينــت قريبــا أن مثــل هــذه الكميــة ملثــل‬\n     ‫املدعــى عليــه تعتبــر للتعاطــي ويف نظــري أن الضابــط يف اعتبار الكمية‬\n     ‫يقصــد منهــا الترويــج أو التعاطــي هــو حــال املتهــم ال العــدد فحســب‬\n     ‫وعليــه فأنــا مــا زلــت علــى مــا حكمــت بــه وأمــا بالنســبة للمالحظــة‬\n     ‫الثانيــة فلوجاهتهــا فإنــه ســيتم مراعــاة ذلــك مســتقبال وملشــايخي‬\n     ‫أصحــاب الفضيلــة الشــكر والتقديــر والدعــاء بــأن يوفقهــم اهلل ملــا فيــه‬\n     ‫خيــري الدنيــا واآلخــرة هــذا مــا جــرى ضبطــه حتــى ال يخفــى وســيجري‬\n\n\n‫‪65‬‬\n\f‫التهميــش بذلــك علــى القــرار وإعــادة كامــل املعاملــة حملكمــة‬\n‫االســتئناف لتدقيــق احلكــم‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/04/10‬هـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق ‪/ 6 / 21‬‬\n‫‪ 1424‬هـ ـ فتحــت اجللســة الســاعة الواحــدة والنصــف بعــد الظهــر وفيهــا‬\n‫جــرى االطــاع علــى القــرار رقــم ‪ 34226785‬وتاريــخ ‪1434/5/29‬ه ـ‬\n‫الصــادر مــن أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة اجلزائيــة‬\n‫األولــى مبحكمــة االســتئناف مبنطقــة تبــوك املشــفوع مــع املعاملــة‬\n‫الــواردة بخطــاب فضيلــة رئيســها رقــم ‪ 3435479‬يف ‪1434/6/4‬ه ـ‬\n‫واملتضمــن املصادقــة علــى احلكــم باألكثريــة بعــد اإلجــراء األخيــر‬\n‫واملظهــر مبضمونــه علــى القــرار الصــادر منــي برقــم ‪3426395‬وتاريــخ‬\n‫‪ 1434/ 1/ 28‬ه ـ وحيــث جــاء يف قــرار أصحــاب الفضيلــة قضــاة‬\n‫االســتئناف املشــار لــه بعاليــه تنبيههــم الكــرمي بإضافــة مــا أجبــت بــه‬\n‫علــى املالحظــة الثانيــة علــى احلكــم وحيــث ظهــر لــي وجاهــة مــا الحظــه‬\n‫أصحــاب الفضيلــة يف مالحظتهــم الثانيــة املوضحــة يف قرارهــم الســابق‬\n‫رقــم ‪ 3454878‬وتاريــخ ‪1434/3/3‬ه ـ لــذا فإنــي قــررت اآلتــي‪ :‬أوصــي‬\n‫بعــرض املدعــى عليــه علــى جلنــة طبيــة للكشــف عليــه فــإن ثبــت إدمانــه‬\n‫يعالــج وحتتســب مــدة عالجــه مــن مــدة احلكــم بســجنه احملكــوم بهــا‬\n‫آنفــا وبذلــك حكمــت ويف هــذه اجللســة حضــر املدعــي العــام واملدعــى‬\n‫عليــه وأحطتهمــا مبــا مت إضافتــه آنفــا و ألال يخفــى جــرى إحلاقــه بضبطــه‬\n‫ويعــد مــا حكمــت بــه نهائي ـ ًا مكتســب ًا للقطعيــة بعــد تصديقــه مــن‬\n‫محكمــة االســتئناف بحســب املــادة ‪ 213‬مــن نظــام اإلجــراءات اجلزائيــة‬\n‫التــي نصــت علــى أن احلكــم املصــدق مــن التمييــز يعــد حكم ـ ًا نهائي ـ ًا‬\n\n\n                                                                                  ‫‪66‬‬\n\f     ‫وســيجري بعــث املعاملــة متضمنــة القــرار الشــرعي الصــادر باحلكــم‬\n     ‫إلــى احلاكــم اإلداري عــن طريــق رئيــس احملكمــة لتنفيــذ احلكــم‬\n     ‫بنــاء علــى املادتــن (‪ )219-215‬مــن النظــام املشــار إليــه بعاليــه وبــاهلل‬\n     ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                             ‫يف ‪1434/06/21‬ه ـ‬\n\n\n\n\n‫‪67‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":57,"source_page_end":67,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"da4f73280758242d930056975a1cacf49c98e381b8887dca564b38ec7737dac3","normalized_text_hash":"0028780314af194bca048907e909e414c99278f960072183f6958012210f1e02","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p57-3426395"},{"id":"e6f1a976-3245-530d-a527-52de42385c9f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -وقيادة السيارة حتت تأثير املخدر -اعتداء على رجال األمن -تعزير للتهمة القوية -التعزير بالسجن واجللد واملنع من السفر .","document_number":"3412393","case_number":"3415847","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/14","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -وقيادة السيارة حتت تأثير املخدر -اعتداء على رجال األمن -تعزير للتهمة القوية -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3412393:‬تاريخه‪1434/01/14 :‬هـ‬\n                    ‫رقم الدعوى‪3415847:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3414969‬تاريخه‪1434/01/18 :‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيها ‪ -‬وقيادة‬\n‫الســيارة حتــت تأثيــر املخــدر‪ -‬اعتــداء علــى رجــال األمــن ‪ -‬تعزيــر‬\n     ‫للتهمــة القويــة ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n               ‫املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلبــوب احملظورة‬\n‫بقصــد التعاطــي وتعاطيــه لهــا وقيادتــه الســيارة حتــت تأثيرهــا ومقاومــة‬\n‫رجــال األمــن واالعتــداء عليهــم ومحاولــة الهــرب منهــم‪ ،‬واحلكــم عليــه‬\n‫بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة مــع إفهامــه بــأن عقوبــة القيــادة حتــت تأثيرهــا تقــرر‬\n‫مــن اجلهــة املختصــة وإيقــاع عقوبــة تعزيريــة عليــه علــى باقــي التهــم‪،‬‬\n‫حيــث أنــه مت تفتيــش الســيارة التــي يقودهــا املدعــى عليــه فعثــر فيها على‬\n‫حبــوب اإلمفيتامــن احملظــورة‪ ،‬وأثبــت التقريــر الكيمــاوي الشــرعي‬\n‫إيجابيــة العينــة املرســلة لإلمفيتامــن ‪ ،‬كمــا أقــر أمــام احملكمــة مبــا‬\n‫أســنده إليــه املدعــي العــام مــن التعاطــي والقيــادة حتــت تأثيــره ومقاومــة‬\n‫رجــال األمــن أثنــاء القبــض عليــه وأنكــر احليــازة‪ ،‬طلبــت احملكمــة مــن‬\n\n                                                                                     ‫‪68‬‬\n\f     ‫املدعــي العــام تقــدمي بيناتــه وقــررت ســماع شــهادة شــهود محضــر القبــض‬\n     ‫فشــهد شــاهد واحــد منهــم فقط بوجــود احلبوب احملظورة داخل الســيارة‬\n     ‫فقضــت احملكمــة بإدانــة املدعــى عليــه بالتعاطــي والقيــادة حتــت تأثيــره‬\n     ‫وقــررت جلــده ســبعني جلــدة دفعــة واحــدة وأفهمتــه بــأن عقوبتــه علــى‬\n     ‫القيــادة حتــت تأثيــره تقــرر مــن اجلهــة املختصــة‪ ،‬كمــا قضــت بإدانتــه‬\n     ‫مبقاومــة رجــال األمــن ومحاولــة الهــرب منهــم وقــررت ســجنه ملــدة‬\n     ‫شــهر ونصــف وجلــده خمســن جلــدة كمــا قضــت بعــدم ثبــوت حيازتــه‬\n     ‫للحبــوب احملظــورة إال أنهــا قــررت تعزيــره للتهمــة القويــة الناجتــة عــن‬\n     ‫شــهادة الشــاهد بســجنه ملــدة أربعــة أشــهر‪ ،‬قنــع املدعــى عليــه باحلكــم‬\n     ‫وعــارض املدعــي العــام عليــه‪ ،‬وقــررت محكمــة االســتئناف املصادقــة‬\n                                                                        ‫علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا‪ .......‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة‬\n     ‫لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر برقــم‬\n     ‫‪ 3415847‬وتاريخ ‪1434/01/10‬هـ املقيدة باحملكمة برقم ‪3474807‬‬\n     ‫وتاريــخ ‪1434/01/10‬ه ـ ففــي يــوم االثنــن املوافــق ‪1434/01/12‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 9 :30‬وفيهــا قــدم املدعــي العــام الئحــة دعــوى‬\n     ‫عامــه ضــد ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).......‬‬\n     ‫ا فيهــا حيــث إنــه باالطــاع علــى محضــري البــاغ واالنتقــال‬              ‫قائ ـ ً‬\n     ‫والقبــض والتفتيــش املعديــن مــن قبــل رجــال مكافحــة املخــدرات‬\n     ‫بالدمــام تبــن انــه يف يــوم الثالثــاء املوافــق ‪1433/11/16‬ه ـ وردتهــم‬\n\n‫‪69‬‬\n\f‫معلومــات مــن احــد مصادرهــم الســرية عــن قيــام املدعــى عليــه بترويــج‬\n‫احلبــوب احملظــورة وهــو مــن احلذريــن جــدا ويتجــول أكثــر أوقاتــه يف حــي‬\n‫الثقبــة علــى ســيارة نــوع ‪ ، .......‬واســتعد املصــدر باإلبــاغ عنــه عنــد‬\n‫حيــازة املدعــى عليــه للمــواد املخــدرة ‪ ،‬وعنــد الســاعة الســابعة والنصــف‬\n‫ـاء ذكــر املصــدر بــأن املدعــى عليــه يتواجــد بالثقبــة ويقــوم بنشــر‬ ‫مسـ ً‬\n‫ســمومه علــى بعــض األشــخاص ‪ ،‬فتــم انتقالهــم للموقــع احملــدد وعنــد‬\n‫وصولهــم شــوهد املدعــى عليــه علــى شــارع ‪ ........‬يقــود ســيارة مــن نــوع‬\n‫‪ .....‬ويتقابــل مــع بعــض األشــخاص املشــبوهني وســلم ألحــد األشــخاص‬\n‫شــيء مــا واســتلم منــه مبلــغ وذلــك حتــت أنظــار أفــراد الفرقــة القابضــة‬\n‫فجــرى متابعتــه حتــى توقــف عنــد احــد احملــات التجاريــة فتــم اســتيقافه‬\n‫وبتفتيشــه لــم يعثــر بحوزتــه علــى شــيء مــن املمنوعــات وقــام مبقاومــة‬\n‫أفــراد الفرقــة القابضــة مقاومــة عنيفــة محــاوال اإلفــات منهمــا‬\n‫والتمكــن مــن ركــوب ســيارته ممــا أدى إلــى بعــض اإلصابــات بجنديني‬\n‫مــن أفــراد الفرقــة القابضــة جــرى بعثهما للمستشــفى املركــزي بالدمام‬\n‫لتلقــي العــاج الــازم‪ ،‬وقــام بضــرب مقدمــة رأســه ببــاب الســيارة‬\n‫الرســمية ‪ ،‬وبتفتيــش ســيارته التــي كانــت بقيادتــه عثــر بداخلهــا حتــت‬\n‫ديكــور ناقــل احلركــة علــى عــدد (‪ )5‬خمــس حبــات أثبــت التقريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ 4098‬ك ش) وتاريــخ ‪ 1433/11/21‬ه ـ‬\n‫إيجابيتهــا جميعــا كال علــى حــده ملــادة اإلمفيتامــن املنبهــة احملظــورة ‪،‬‬\n‫املــدرج يف اجلــدول ( ‪ ) 2‬فئــة (ب) مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة فتــم القبــض عليــه واعتــرف املدعــى عليــه ألفــراد‬\n‫الفرقــة القابضــة حــال القبــض عليــه بصحــة واقعــة الضبــط وبســماع‬\n‫أقــوال املتهــم األوليــة أنكــر حيازتــه احلبــوب املنبهــة املضبوطــة واقــر‬\n\n\n                                                                                   ‫‪70‬‬\n\f     ‫مبقاومــة رجــال األمــن‪ ،‬نافيــا تعاطيــه أي نــوع مــن أنــواع املخــدرات‬\n     ‫وباســتجوابه نفــى حيازتــه احلبــوب املنبهــة املضبوطــة واقــر بتعاطــي‬\n     ‫احلبــوب املنبهــة منــذ خمــس ســنوات وأخــر مــرة كانــت قبــل القبــض‬\n     ‫عليــه بســاعة أثنــاء قيادتــه الســيارة وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n     ‫لــ‪ .......‬بحيــازة خمــس حبــات مــن حبــوب اإلمفيتامــن املنبهــة احملظــورة‬\n     ‫بقصــد التعاطــي وتعاطــي احلبــوب املنبهــة احملظــورة ومقاومــة رجــال‬\n     ‫األمــن واالعتــداء عليهــم ومحاولــة الهــرب اثنــاء القبــض عليــه وقيــادة‬\n     ‫الســيارة حتــت تأثيــر احلبــوب املنبهــة احملظــورة وذلــك لألدلــة والقرائــن‬\n     ‫التاليــة‪ -1:‬مــا ورد باســتجوابه املنــوه عنــه املرفــق علــى اللفــات رقــم (‪-13‬‬\n     ‫‪ ، )15‬ومــا ورد بأقوالــه األوليــة املدونــة علــى الصفحتــن رقــم (‪)22-21‬‬\n     ‫مــن ملــف التحقيــق ‪ -2‬محضــري البــاغ و االنتقــال و القبــض والتفتيــش‬\n     ‫املنــوه عنهمــا املدونــن علــى الصفحتــن رقــم(‪ )13-12 ، 2‬مــن ملــف‬\n     ‫التحقيــق ‪ -3‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة‬\n     ‫رقم(‪)16‬وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه علــى ســابقتني‬\n     ‫األولــى ســرقة أمــوال والثانيــة ترويــج املخــدرات وحيــث إن مــا أقــدم عليــه‬\n     ‫املدعــى عليــه ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ ،‬فعــل محــرم‬\n     ‫ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا أطلــب اآلتــي‪ :‬أوال‪ /‬بإثبــات حيازتــه‬\n     ‫خمــس حبــات مــن حبــوب اإلمفيتامــن املنبهــة احملظــورة بقصــد‬\n     ‫التعاطــي‪ ،‬وتعاطيــه نوعهــا وفــق الفقــرة رقــم(‪ )2‬مــن املــادة رقــم (‪ )3‬مــن‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا‬\n     ‫يلــي‪ -1:‬بعقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪)41‬‬\n     ‫مــن النظــام ‪ -2‬منعــه مــن الســفر وفــق الفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n     ‫(‪ )56‬مــن النظــام ثانيــا‪ /‬إثبــات مقاومتــه رجــال األمــن واالعتــداء عليهــم‬\n\n\n‫‪71‬‬\n\f‫ومحاولــة الهــرب اثنــاء القبــض عليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n‫رادعــة ‪ ،‬والتشــديد عليــه وفقــا لتعميــم النائــب الثانــي لرئيــس مجلــس‬\n‫الــوزراء وزيــر الداخليــة رقــم (‪ )118012‬وتاريــخ ‪1430/10/26‬ه ـ‬\n‫ملقاومتــه رجــال األمــن ‪ ،‬ولكونــه عســكري ًا اســتناد ًا إلــى برقيتــي‬\n‫صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪)112103/4/5/1‬‬\n‫وتاريــخ ‪1429/11/4‬هــ‪ ،‬ورقــم (‪ )10130/4/5/1‬وتاريــخ‬\n‫‪1429/2/15‬ه ـ ثالثــا‪ /‬إثبــات قيادتــه الســيارة حتــت تأثيــر احلبــوب‬\n‫املنبهــة احملظــورة وفــق الفقــرة رقــم ( ‪ ) 8‬مــن اجلــدول رقــم ( ‪ ) 1‬امللحــق‬\n‫بنظــام املــرور وإفهامــه أن عقوبتــه الــواردة بالفقــرة رقــم( ‪ ) 1‬مــن املــادة‬\n‫رقــم( ‪ ) 68‬مــن نظــام املــرور تقــرر مــن اجلهــة املختصــة وفــق الفقــرة( ‪) 2‬‬\n‫مــن قــرار مجلــس الــوزراء رقــم ( ‪ ) 315‬يف ‪1428/10/24‬ه ـ (علمــا بــان‬\n‫احلــق اخلــاص لــم ينته)هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى‬\n‫أجــاب بقولــه مــا جــاء يف الدعــوى مــن حيازتــي خمــس حبــات محظــورة‬\n‫بقصــد االســتعمال هــذا غيــر صحيــح ومــا جاء يف الدعوى من اســتعمالي‬\n‫احلبــوب احملظــورة وقيادتــي الســيارة حتــت تأثيــر احلبــوب احملظــورة‬\n‫ومقاومتــي رجــال األمــن عنــد القبــض علــي هــذا كلــه صحيــح ففــي‬\n‫تاريــخ ‪1433/11/16‬ه ـ كنــت أقــود ســيارتي نــوع ‪ .....‬انتــاج‪2000‬م يف‬\n‫حــي الثقبــة وتوقفــت عنــد مغســلة مالبــس علــى شــارع ‪ .....‬كــي آخــذ‬\n‫مالبســي وعندهــا حضــر رجــال مكافحــة املخــدرات وقبضــوا علــي‬\n‫وقامــوا بتفتيشــي فلــم يعثــروا معــي علــى شــيء ثــم أركبونــي معهــم‬\n‫وأخــذوا يتنقلــون بســيارتهم حــول املوقــع وأنــا معهــم ثــم اتهمونــي بحيــازة‬\n‫احلبــوب احملظــورة فقمــت مبقاومتهــم ومدافعتهــم محــاو ًال التفلــت منهــم‬\n‫والهــرب هــذا مــا حصــل والســيارة ‪ ......‬املذكــورة يف الدعــوى ال عالقــة‬\n\n\n                                                                                      ‫‪72‬‬\n\f     ‫لــي بهــا علم ـ ًا بأنــي اســتعمل احلبــوب احملظــورة وآخــر مــرة اســتعملت‬\n     ‫فيهــا احلبــوب احملظــورة كانــت قبــل القبــض علــي بســاعة وقــد قمــت‬\n     ‫بقيــادة الســيارة حتــت تأثيــر احلبــوب احملظــورة ومــا ذكــره املدعــي العــام‬\n     ‫مــن ســوابقي فهــو صحيــح وأنــا أعمــل عســكري يف ‪ .......‬هكــذا أجــاب‬\n     ‫وبســؤال املدعــي العــام البينــة علــى دعــواه قــال بينتــي مــا ذكــرت فجــرى‬\n     ‫الرجــوع إلــى اللفــة رقــم (‪ )15‬وتضمنــت ضبــط إفــادة املدعــى عليــه وقــد‬\n     ‫أنكــر حيازتــه احلبــوب احملظــورة كمــا جــرى الرجــوع إلى إفــادة املدعى‬\n     ‫عليــه املدونــة علــى الصفحــة رقــم (‪ )21‬مــن ملــف التحقيــق املرفــق لفــه‬\n     ‫رقــم (‪ )1‬وقــد أنكــر حيازتــه للحبــوب احملظــورة ثــم أقفلــت اجللســة‬\n     ‫الســاعة العاشــرة والثلــث لطلــب معــدي محضــر القبــض وصلــى اهلل‬\n     ‫وســلم علــى نبينــا محمــد احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم‬\n     ‫الســبت ‪1434/1/17‬ه ـ الســاعة التاســعة والربــع افتتحــت اجللســة‬\n     ‫بحضــور املدعــى عليــه كمــا حضــر الشــاهد ‪ .......‬ســعودي بالســجل‬\n     ‫املدنــي رقــم‪ .......‬وهــو أحــد معــدي محضــر القبــض علــى املدعــى عليــه‬\n     ‫وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل أنــه توفــرت معلومــات‬\n     ‫لدينــا يف مكافحــة املخــدرات عــن قيــام املدعــى عليــه بترويــج احلبــوب‬\n     ‫احملظــورة ويف تاريــخ ‪1433/11/16‬ه ـ أخبرنــا املصــدر الســري بوجــود‬\n     ‫املدعــى عليــه يف حــي الثقبــة وبحوزتــه احلبــوب احملظــورة فانتقلــت مــع‬\n     ‫الفرقــة القابضــة للموقــع وقــد شــاهدت املدعــى عليــه يقــود ســيارة ‪......‬‬\n     ‫لونهــا أبيــض يف الشــارع ‪ ......‬بحــي الثقبــة وقــد توقــف عنــد أحــد‬\n     ‫األشــخاص وقــام املدعــى عليــه بإعطــاء ذلــك الشــخص شــيئ ًا مــا واســتلم‬\n     ‫منــه شــيئ ًا مــا ال أعلــم مــا هــو ثــم حتــرك املدعــى عليــه بالســيارة ‪........‬‬\n     ‫حتــى توقــف عنــد مغســلة مالبــس فنــزل مــن الســيارة ودخــل املغســلة‬\n\n\n‫‪73‬‬\n\f‫فتوقفنــا خلفــه ونزلنــا للمغســلة وطلبنــا مــن املدعــى عليــه إثباتــه ثــم‬\n‫ســألناه عــن ســيارته فأفــاد بأنــه ال يوجــد معــه ســيارة وملــا علــم بأننــا‬\n‫ســوف نقــوم بتفتيــش الســيارة ‪ ..........‬قــام مبقاومتنــا مقاومــة شــديدة ومت‬\n‫إركابــه بســيارة املكافحــة ثــم انتقلــت أنــا للســيارة ‪ ........‬التــي كان‬\n‫يقودهــا املدعــى عليــه وقمــت بتفتيشــها فوجــدت حتــت ديكــور ناقــل‬\n‫احلركــة (القيــر) خمــس حبــات محظــورة داخــل كيــس ولــم يشــاهدني‬\n‫أحــد مــن زمالئــي عندمــا وجــدت احلبــوب احملظــورة داخــل الســيارة حيث‬\n‫إنهــم كانــوا يف ســيارة املكافحــة مــع املدعــى عليــه وكنــت أقــوم‬\n‫بتفتيــش الســيارة لوحــدي وعندمــا علــم املدعــى عليــه أني وجــدت احلبوب‬\n‫احملظــورة يف الســيارة ‪ .......‬قــام مبقاومتنــا مــرة أخــرى مقاومــة شــديدة‬\n‫هــذا مــا لــدي مــن شــهادة كمــا حضــر الشــاهد ‪ .......‬ســعودي بالســجل‬\n‫املدنــي رقــم‪ .......‬وهــو أحــد معــدي محضــر القبــض علــى املدعــى عليــه‬\n‫وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل أنــه توفــرت معلومــات‬\n‫لدينــا يف مكافحــة املخــدرات عــن قيــام املدعــى عليــه بترويــج احلبــوب‬\n‫احملظــورة ويف تاريــخ ‪1433/11/16‬ه ـ أخبرنــا املصــدر الســري بوجــود‬\n‫املدعــى عليــه يف حــي ‪ .......‬وبحوزتــه احلبــوب احملظــورة فانتقلــت مــع‬\n‫الفرقــة القابضــة للموقــع وقــد شــاهدنا املدعــى عليــه يقــود ســيارة ‪.......‬‬\n‫لونها أبيض يف الشارع ‪ ........‬بحي ‪ .......‬وقد توقف عند أحد األشخاص‬\n‫وقــام املدعــى عليــه بإعطــاء ذلــك الشــخص شــيئ ًا مــا واســتلم منــه شــيئ ًا‬\n‫مــا ال أعلــم مــا هــو ثــم حتــرك املدعــى عليــه بالســيارة ‪ .....‬حتــى توقــف‬\n‫عنــد مغســلة مالبــس فنــزل مــن الســيارة ودخــل املغســلة فتوقفنــا خلفــه‬\n‫ونزلنــا للمغســلة وطلبنــا مــن املدعــى عليــه إثباتــه ثــم ســألناه عــن ســيارته‬\n‫فأفــاد بأنــه ال يوجــد معــه ســيارة وملــا علــم بأننــا ســوف نقــوم بتفتيــش‬\n\n\n                                                                                        ‫‪74‬‬\n\f     ‫الســيارة ‪ ......‬قــام مبقاومتنــا مقاومــة شــديدة وقمنــا بإركابــه بســيارة‬\n     ‫املكافحــة ثــم ذهــب زميلــي لتفتيــش الســيارة ‪ .......‬لوحــده ورجــع ومعــه‬\n     ‫كيــس بداخلــه خمــس حبــات محظــورة يقــول بأنــه وجدهــا يف الســيارة‬\n     ‫‪ ........‬فقــام املدعــى عليــه مبقاومتنــا مــرة أخــرى هــذا مــا لــدي مــن شــهادة‬\n     ‫هكــذا شــهدا وبعــرض الشــاهدين وشــهادتهما علــى املدعــى عليــه قــال‬\n     ‫الشــاهدين ال أعلــم عــن حالهمــا وهمــا مــن قامــا بالقبــض علـ ّـي وأمــا‬\n     ‫شــهادتهما مــن أنــي كنــت أقــود ســيارة ‪ ........‬وتوقفــت عنــد أحــد‬\n     ‫األشــخاص وأعطيتــه شــيئ ًا مــا واســتلمت منــه شــيئ ًا مــا هــذا كلــه غيــر‬\n     ‫صحيــح ومــا ذكــره الشــاهد مــن أنــه وجــد يف الســيارة ‪ .........‬حبوب ـ ًا‬\n     ‫محظــورة هــذا ال عالقــة لــي بــه فهــذه الســيارة ال تعــود لــي وأمــا مقاومــة‬\n     ‫الفرقــة القابضــة فقــد قمــت مبقاومتهــم بعــد أن اتهمونــي بحيــازة احلبــوب‬\n     ‫احملظــورة هكــذا قــرر وبســؤال الشــاهدين عــن مالــك الســيارة ‪............‬‬\n     ‫قــال كل واحــد منهمــا الســيارة تعــود لشــركة تأجيــر ســيارات‬\n     ‫واملســتأجر شــخص آخــر غيــر املدعــى عليــه هكــذا قــررا وقــد حضــر‬\n     ‫‪.......‬ســعودي بالســجل املدنــي رقــم ‪ .......‬ســعودي بالســجل املدنــي‬\n     ‫رقــم‪ .......‬وجــرى تعديــل الشــاهدين التعديــل الشــرعي بعــد ذلــك جــرى‬\n     ‫الرجــوع إلــى اللفــة رقــم (‪ )16‬وتضمنــت التقريــر الكيمــاوي الشــرعي‬\n     ‫وهــو كمــا ذكــر املدعــي العــام يف دعــواه ثــم أقفلــت اجللســة الســاعة‬\n                        ‫العاشرة والربع للتأمل وصلى اهلل وسلم على نبينا محمد‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم األحــد ‪1434/ 1/18‬ه ـ‬\n     ‫الســاعة الثامنــة والنصــف افتتحــت اجللســة بحضــور املدعــى عليــه خالــد‬\n     ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬     ‫فبنـ ً‬\n     ‫باســتعمال احلبــوب احملظــورة وقيــادة الســيارة حتــت تأثيــر احلبــوب‬\n\n\n‫‪75‬‬\n\f‫احملظــورة ومقاومــة رجــال األمــن ومدافعتهــم محــاو ًال الهــرب وحيــث‬\n‫أنكــر املدعــى عليــه حيــازة احلبــوب احملظــورة وحيــث إنــه ال بينــة مثبتــة‬\n‫لذلــك فــا يوجــد ســوى شــاهد واحــد علــى أنــه وجــد يف الســيارة ‪......‬‬\n‫خمــس حبــات محظــورة وحيــث إن التهمــة القويــة متوجهــة للمدعــى عليــه‬\n‫بحيــازة اخلمــس حبــات احملظــورة وذلــك ملــا جــاء يف شــهادة الشــاهدين من‬\n‫أن املدعى عليه كان يقود الســيارة ‪ ........‬وشــهادة الشــاهد من أنه وجد‬\n‫خمــس حبــات محظــورة داخــل الســيارة ‪ .......‬التــي كان يقودهــا املدعــى‬\n‫عليــه وقــد قــرر الشــاهد بأنــه لــم يشــاهده أحــد مــن زمالئــه عندمــا وجــد‬\n‫هــذه احلبــوب احملظــورة داخــل ســيارة املدعــى عليــه وحيــث إن املدعــى‬\n‫عليــه عســكري يف ‪ .......‬وملــا جــاء يف املــادة السادســة واخلمســن مــن‬\n‫نظــام مكافحــة املخــدرات وحيــث إن املــادة احلاديــة واألربعــن مــن ذات‬\n‫النظــام خاصــة باحليــازة وملــا جــاء يف التقريــر الكيمــاوي الشــرعي لــذا‬\n‫فقــد قــررت مــا يلــي أو ًال ثبــت لــدي اســتعمال املدعــى عليــه للحبــوب‬\n‫احملظــورة وقــررت تعزيــره لقــاء ذلــك بجلــده ســبعني جلــده ومنعــه مــن‬\n‫الســفر خــارج اململكــة مــدة ســنتني بعــد تنفيــذ عقوبتــه ثانيـ ًا عــدم ثبــوت‬\n‫دعــوى املدعــي العــام جتــاه املدعــى عليــه مــن حيازتــه خمــس حبــات مــن‬\n‫حبــوب اإلمفيتامــن املنبــه احملظــور وقــد توجهــت التهمــة القويــة للمدعــى‬\n‫عليــه بذلــك وقــررت تعزيــره لقــاء هــذه التهمــة بســجنه مــدة أربعــة أشــهر‬\n‫ثالثـ ًا ثبــت لــدي مقاومــة املدعــى عليــه لرجــال األمــن ومدافعتهــم محــاو ًال‬\n‫الهــرب وقــررت تعزيــره لقــاء ذلــك بســجنه مــدة شــهر ونصــف وجلــده‬\n‫خمســن جلــده وبذلــك يكــون مجمــوع ســجن املدعــى عليــه هــو خمســة‬\n‫أشــهر ونصــف اعتبــار ًا مــن تاريــخ إيقافــه ومجمــوع جلــده هــو مائــة‬\n‫وعشــرين جلــده علــى ثــاث دفعــات متســاوية بــن الدفعــة واألخــرى مــدة‬\n\n\n                                                                                       ‫‪76‬‬\n\f     ‫ال تقــل عــن عشــرة أيــام رابع ـ ًا ثبــت لــدي قيــادة املدعــى عليــه للســيارة‬\n     ‫حتــت تأثيــر احلبــوب احملظــورة وأفهمتــه أن عقابــه علــى ذلــك عائــد للجهة‬\n     ‫املختصــة خامسـ ًا عــدم إجابــة املدعــي العــام فيمــا طلبــه مــن تطبيــق املــادة‬\n     ‫احلاديــة واألربعــن مــن نظــام مكافحــة املخــدرات علــى املدعــى عليــه‬\n     ‫لقــاء اســتعماله احلبــوب احملظــورة ومبــا تقــدم حكمــت وبعــرض احلكــم‬\n     ‫قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفيـ ًا مبــا قــدم يف الئحــة‬\n     ‫الدعــوى وأقفلــت اجللســة الســاعة التاســعة وصلــى اهلل وســلم علــى نبينــا‬\n                                                                                    ‫محمــد‪.‬‬\n     ‫احلمــدهلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪/34/248322‬ج‪ 2‬وتاريــخ ‪ 1434/1/28‬ه ـ‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبراملكلــف‬\n     ‫برقــم ‪ 3474807‬وتاريــخ ‪ 1434/1/24‬ه ـ املرفــق بهــا القــرار الصــادر‬\n     ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...... /‬املســجل برقــم‪3414969‬‬\n     ‫وتاريــخ ‪ 1434/1/18‬ه ـ اخلــاص بدعــوى ‪ /‬املدعــي العــام ضــد ‪...... /‬‬\n     ‫يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مباهــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                         ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/2/5‬ه ـ ‪.‬‬\n\n\n\n\n‫‪77‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":68,"source_page_end":77,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5fe09de4324877a3091f813eef90d5ffcdb87baf86cc85b094e07c7d855c23d2","normalized_text_hash":"91a2526609229ece71b862af9c64ffa18f6d5247b8c7df1415d2070d4a5ad09f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p68-3412393"},{"id":"85becc9b-028a-5e3b-b6a9-6871f135ede3","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -عدم قبول الرجوع عن اإلقرار -إدانة -تطبيق حد املسكر على متعاطي احلشيش -نزول عن احلد األدنى للعقوبة -التعزير بالسجن","document_number":"3443176","case_number":"3419016","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/20","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -عدم قبول الرجوع عن اإلقرار -إدانة -تطبيق حد املسكر على متعاطي احلشيش -نزول عن احلد األدنى للعقوبة -التعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3443176 :‬تاريخه‪1434/02/20 :‬هـ‬\n                     ‫رقم الدعوى‪3419016:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪3460766‬تاريخه‪1434/03/11:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬عــدم قبــول‬\n‫الرجــوع عــن اإلقــرار‪ -‬إدانــة ‪ -‬تطبيــق حــد املســكر علــى متعاطــي‬\n‫احلشــيش ‪ -‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬التعزيــر بالســجن‬\n                                                              ‫واإلبعــاد‪.‬‬\n\n\n\n\n‫‪ -1‬القاعــدة الفقهيــة‪{ :‬املــرء مؤاخــذ بإقــراره}‪ ،‬والقاعــدة الفقهيــة‪:‬‬\n‫{إقــرار اإلنســان علــى نفســه مقبــول}‪ .‬املنثــور مــن القواعــد للزركشــي‬\n‫[ج‪ ]188/1‬واألشباه والنظائر للسيوطي [ج‪ ]465/1‬ودرر احلكام [ج‪.]79/1‬‬\n‫‪ -2‬املــادة (‪ )3‬والفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪ )2‬مــن املــادة (‪)56‬‬\n‫والفقــرة (‪ )1‬مــن املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                     ‫العقليــة‪.‬‬\n‫‪ -3‬التعميــم رقــم ‪/13‬ت‪ 939/‬يف ‪1417/6/25‬ه ـ والتعميــم رقــم‬\n                                       ‫‪/13‬ت‪ 1625/‬يف ‪1421/8/26‬هــ‪.‬‬\n\n\n\n‫دعــوى املدعــي العــام ضــد املدعــى عليهمــا تتضمــن طلــب إثبــات إدانتهمــا‬\n‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطيهمــا لــه ‪ ،‬واحلكــم‬\n‫عليهمــا بعقوبــة الســجن واإلبعــاد عــن البــاد طبقــا لنظــام مكافحــة‬\n\n                                                                                    ‫‪78‬‬\n\f     ‫املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث إنــه مت تفتيــش املدعــى عليــه األول‬\n     ‫شــخصيا فعثــر بحوزتــه علــى قطعــة مــن احلشــيش املخــدر وأثبــت التقريــر‬\n     ‫الكيمــاوي الشــرعي إيجابيــة العينة املرســلة للحشــيش املخــدر‪ ،‬اعترفا‬\n     ‫حتقيق ـ ًا بحيازتهمــا للحشــيش املخــدر بقصــد التعاطــي وتعاطيهمــا مــن‬\n     ‫نوعــه أقــر املدعــى عليــه األول أمــام احملكمــة مبــا أســنده إليــه املدعــي‬\n     ‫العــام وأقــر الثانــي بتعاطــي احلشــيش املخــدر وأنكــر اشــتراكه يف‬\n     ‫حيازتــه‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإدانــة املدعــى عليهمــا‬\n     ‫بجميــع مــا نســب إليهمــا وقــررت ســجن األول ملــدة أربعــة أشــهر وســجن‬\n     ‫الثانــي ملــدة ثالثــة أشــهر وجلــد كل واحــد منهمــا حــد املســكر ثمانــن‬\n     ‫جلــدة يف مــكان عــام وإبعادهمــا عــن البــاد بعد انتهــاء محكوميتهما‪،‬‬\n     ‫قنــع املدعــى عليهمــا باحلكــم وعــارض املدعــي العــام عليــه و قــررت‬\n                                    ‫محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد وبنــاء علــى املعاملــة املقيــدة بهــذه احملكمــة برقــم‬\n     ‫‪ 3490856‬يف ‪1434/1/12‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيــس برقــم‬\n     ‫‪ 3419016‬يف ‪1434/1/25‬ه ـ يف القضيــة رقــم (‪ )3301700573‬ويف‬\n     ‫يــوم األحــد املوافــق ‪1434/1/25‬ه ـ افتتحــت اجللســة األولــى يف هــذه‬\n     ‫الدعــوى يف متــام الســاعة الثامنــة والربــع صباحــا وفيهــا حضــر املدعــي‬\n     ‫العــام وحضــر حلضــوره املدعــى عليهمــا كال مــن ‪....... -1‬ـ البالــغ مــن‬\n     ‫العمــر ( ‪ ) 25‬عام ـ ًا ـ ـ مصــري اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n     ‫(‪ )..............‬مرافــق ‪ ،‬أوقــف بتاريــخ ‪1433/12/1‬ه ـ ومت التمديــد لــه‬\n     ‫مبوجــب أمــر التمديــد رقــم (‪ )........‬وتاريــخ ‪1433/12/9‬ه ـ وأحيــل‬\n\n‫‪79‬‬\n\f‫لشــعبة ســجن محافظــة االحســاء اســتناد ًا لبرقيــة وزيــر الداخليــة رقــم‬\n‫(‪ )........‬وتاريخ ‪1432/12/20‬هـ‪....... -2 .‬ـ البالغ من العمر ( ‪ ) 26‬عام ًا‬\n‫ـ ـ مصــري اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪)...........................‬‬\n‫مهنــدس كهربائــي ‪ ،‬أوقــف بتاريــخ ‪1433/12/1‬ه ـ ومت التمديــد لــه‬\n‫مبوجــب أمــر التمديــد رقــم (‪ )........‬وتاريــخ ‪1433/12/9‬ه ـ وأحيــل‬\n‫لشــعبة ســجن محافظــة االحســاء اســتناد ًا لبرقيــة وزيــر الداخليــة رقــم‬\n‫(‪ )........‬وتاريــخ ‪1432/12/20‬هــ‪ .‬فباالطــاع علــى محضــر القبــض‬\n‫تبــن أنــه بتاريــخ ‪1433/12/1‬ه ـ أثنــاء قيــام دوريــات أمــن الطــرق بعمــل‬\n‫نقطــة تفتيــش بطريــق الدمــام الريــاض الســريع مت اســتيقاف ســيارة‬\n‫مــن نــوع ‪ ......‬موديــل ‪2013‬م اللــون بنــي حتمــل اللوحــة رقــم (‪)).......‬‬\n‫بقيــادة املدعــى عليــه الثانــي ويرافقــه (لــم يوجــه لــه اتهــام) واملدعــى عليــه‬\n‫األول وعنــد طلــب اإلثباتــات لوحــظ عليهــم االرتبــاك وعنــد تفتيشــهم‬\n‫عثــر بحــوزة املدعــى عليــه األول بــن البنطلــون والتيشــيرت علــى قطعــة‬\n‫ســوداء اللــون يحتمــل أن تكــون مــن احلشــيش املخــدر تــزن (‪ )5‬خمــس‬\n‫جرامــات‪ .‬وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪ )........‬لعــام‬\n‫‪1433‬ه ـ ايجابيــة عينــة القطعــة املضبوطــة للحشــيش املخــدر احملظــور‬\n‫واملــدرج يف اجلــدول (‪ )1‬فئــة ( أ ) مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة‪ .‬وباســتجواب املدعــى عليــه األول‪ .......‬أقــر بصحــة‬\n‫واقعــة القبــض والضبــط وحيازتــه للقطعــة املضبوطــة باالشــتراك مــع‬\n‫املدعــى عليــه الثانــي بقصــد التعاطــي وتعاطيــه لنوعهــا‪ .‬وباســتجواب‬\n‫املدعــى عليــه الثانــي‪ .......‬أقــر بصحــة واقعــة القبــض والضبــط وحيازتــه‬\n‫للقطعــة املضبوطــة باالشــتراك مــع املدعــى عليــه األول بقصــد التعاطــي‬\n‫وتعاطيــه لنوعهــا وقــد أســفر التحقيــق عــن توجيــه االتهــام ل ــأول بحيــازة‬\n\n\n                                                                                          ‫‪80‬‬\n\f     ‫قطعــة مــن احلشــيش املخــدر تــزن (‪ )5‬خمــس جرامــات بقصــد التعاطــي‬\n     ‫وتعاطيــه لنوعهــا يف الســابق واتهــام الثانــي باالشــتراك مــع األول يف‬\n     ‫حيــازة قطعــة مــن احلشــيش املخــدر تــزن (‪ )5‬خمــس جرامــات بقصــد‬\n     ‫التعاطــي وتعاطيــه لنوعهــا يف الســابق‪ ،‬املجــرم مبوجــب املــادة ( الثالثــة)‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n     ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وذلــك لألدلــة والقرائــن‬\n     ‫التاليــة‪ -1 - :‬اعترافهمــا املنــوه عنــه املــدون علــى الصفحتــن رقــم (‪)4،3‬‬\n     ‫مــن دفتــر االســتدالل لفــه رقــم (‪ )15‬والصفحتــن رقــم (‪ )2،1‬مــن دفتــر‬\n     ‫التحقيــق لفــة رقــم (‪ -2 .)20‬مــا جــاء يف محضــر الضبــط املرفــق لفــة‬\n     ‫رقــم (‪-2 .)7‬التقريــر الكيمــاوي الشــرعي علــى اللفــة رقــم (‪.)32_31‬‬\n     ‫وبالبحــث عــن ســوابقهما لــم يعثــر لهمــا علــى ســوابق مســجلة‪ .‬وحيــث‬\n     ‫إن مــا أقــدم عليــه املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا‬\n     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا أطلــب إثبــات مــا أســند‬\n     ‫إليهمــا واحلكــم عليهمــا مبــا يلــي‪ .1 -:‬بالعقوبــة الــواردة يف الفقــرة‬\n     ‫األولــى مــن املــادة ( ‪ ) 41‬مــن النظــام املشــار إليــه أعــاه لقــاء مــا أســند‬\n     ‫إليهمــا مــن اتهــام‪ .2 .‬بالعقوبــة الــواردة يف الفقــرة الثانيــة مــن املــادة‬\n     ‫(‪ )56‬مــن النظــام املشــار إليــه أعــاه وذلــك بإبعادهمــا خــارج البــاد بعــد‬\n     ‫تنفيــذ محكوميتهمــا هــذه دعــواي وبســؤال املدعــى عليهمــا عــن دعــوى‬\n     ‫املدعــي العــام أجــاب كال واحــد منهمــا بفــرده قائــا نطلــب تزويدنــا‬\n     ‫بصــورة مــن الئحــة الدعــوى لنتمكــن مــن الــرد عليهــا يف اجللســة القادمــة‬\n     ‫وعليــه قــررت رفــع اجللســة ليــوم األربعــاء املوافــق ‪1434/01/28‬ه ـ قالــه‬\n     ‫ممليــه الفقيــر إلــى عفــو ربــه ‪........‬القاضــي باحملكمــة اجلزئية باألحســاء‬\n     ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى ألــه وصحبــه وســلم حــرر يف‬\n\n\n‫‪81‬‬\n\f                                                                 ‫‪1434/1/25‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/01/28‬ه ـ‬\n‫افتتحــت اجللســة الثانيــة يف متــام الســاعة العاشــرة والربــع صباح ـ ًا يف‬\n‫دعــوى املدعــي العــام ضــد ‪ ........‬و‪ ........‬وفيهــا حضــر املدعــي العــام‬\n‫واملدعــى عليهمــا وبســؤال املدعــى عليهمــا عــن جوابهمــا أجــاب املدعــى‬\n‫األول ‪ ........‬قائـًـا أن مــا ذكــره املدعــي العــام مــن قيامــي حليــازة قطعــة‬\n‫حشــيش مخــدر تــزن خمــس جرامــات بقصــد التعاطــي وقيامــي بتعاطــي‬\n‫نفــس النــوع فصحيــح هكــذا أجــاب كمــا أجــاب املدعــى عليــه الثانــي‬\n‫ا أن مــا ذكــره املدعــي العــام مــن قيامــي بحيــازة احلشــيش‬        ‫‪ .......‬قائ ـ ً‬\n‫املخــدر املوصــوف بالدعــوى لقصــد التعاطــي فغيــر صحيــح وأمــا قيامــي‬\n‫بتعاطــي نفــس النــوع فصحيــح هكــذا أجــاب وبطلــب البينــة مــن املدعــي‬\n‫العــام علــى مــا أنكــره املدعــى عليــه اســتعد بإحضارهــا يف اجللســة‬\n‫القادمــة وعليــه قــرر رفــع اجللســة ليــوم األحــد املوافــق ‪1434/02/17‬ه ـ‬\n‫ومت ختــم اجللســة يف متــام الســاعة احلاديــة عشــر صباحــا قالــه ممليــه‬\n‫الفقيــر إلــى عفــو ربــه ‪........‬القاضــي باحملكمــة اجلزئيــة باألحســاء‬\n‫وللبيــان حــرر يف ‪1434/01/28‬ه ـ وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه صحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق‬\n‫‪1434/2/17‬ه ـ افتتحــت اجللســة الثالثــة يف دعــوى املدعــي العــام ضــد‬\n‫‪........‬ورفيقــه وحضــر املدعــي العــام واملدعــى عليهمــا وبطلــب البينــة التــي‬\n‫وعــد املدعــي العــام بهــا قــال ليــس لــدي ســوى مــا جــاء يف أوراق املعاملــة‬\n‫هكــذا قــال هــذا فتــم اطالعــي علــى محضــر القبــض املرفــق باملعاملــة‬\n‫علــى اللفــة رقــم (‪ )7‬يتضمــن (القبــض علــى املدعــى عليهمــا وبتفتيشــهما‬\n‫عثــر مــع املدعــى عليــه ‪........‬باخلصــر بــن البنطلــون والتيشــيرت علــى‬\n\n\n                                                                                          ‫‪82‬‬\n\f     ‫قطعــة ســوداء يحتمــل أن تكــون حشــيش)أ‪.‬هـ وبعرضــه علــى املدعــى‬\n     ‫عليــه قــال صحيــح هكــذا قــال هــذا فتــم اطالعــي علــى إفــادة املدعــى‬\n     ‫عليــه الثانــي ‪........‬املدونــة علــى صحيفــة رقــم (‪ )6‬مــن ملــف التحقيــق‬\n     ‫املرفــق باملعاملــة علــى اللفــة رقــم (‪ )15‬يتضمــن (إفادتــه بأنــه تعاطــى‬\n     ‫احلشــيش قبــل القبــض عليــه بيــوم وأنــه ال يعلــم عــن املضبوطــات مــع‬\n     ‫املدعــى عليــه ‪........‬أ‪.‬ه ـ وبعرضــه علــى املدعــى عليــه قــال صحيــح‬\n     ‫هكــذا قــال هــذا فتــم اطالعــي علــى إفــادة املدعــى عليــه ‪........‬املدونــة‬\n     ‫علــى صحيفــة رقــم (‪ )1‬مــن ملــف التحقيــق املرفــق باملعاملــة علــى اللفــة‬\n     ‫رقــم (‪ )20‬يتضمــن (إفــادة املدعــى عليــه بأنــه شــريك مــع املدعــى عليــه‬\n     ‫‪........‬يف قطعــة احلشــيش التــي مت العثــور عليهــا مــع ‪)........‬أ‪.‬ه ـ وبعرضــه‬\n     ‫علــى املدعــى عليــه قــال غيــر صحيــح وأنــا اعترفــت بهــذا ألنهــم قالــوا‬\n     ‫لــي اعتــرف بهــذا حتــى يكــون الــكالم واحــد هكــذا قــال هــذا فتــم‬\n     ‫اطالعــي علــى التقريــر الكيمــاوي الشــرعي رقــم (‪ )........‬واملرفــق‬\n     ‫باملعاملــة علــى اللفــة رقــم (‪ )31‬يتضمــن (إيجابيــة مــا ضبــط للحشــيش‬\n     ‫املخدر)أ‪.‬ه ـ هــذا وحلاجتــي لتأمــل القضيــة للنطــق باحلكــم قــررت رفــع‬\n     ‫اجللســة ليــوم األربعــاء املوافــق ‪1434/2/20‬ه ـ قالــه ممليــه الفقيــر إلــى‬\n     ‫عفــو ربه‪........‬القاضــي باحملكمــة اجلزئيــة باألحســاء وصلــى اهلل وســلم‬\n     ‫علــى ســيدنا محمــد حــرر يف ‪1434/2/17‬ه ـ احلمــد هلل وحــده وبعــد‬\n     ‫ويف يــوم األربعــاء املوافــق ‪1434/2/20‬ه ـ افتتحــت اجللســة الرابعــة يف‬\n     ‫دعــوى املدعــي العــام ضــد ‪ ........‬ورفيقــه وفيهــا حضــر املدعــي العــام‬\n     ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار‬‫واملدعــى عليهمــا فبنـ ً‬\n     ‫املدعــى عليهمــا بتعاطــي احلشــيش املخــدر وإقــرار املدعــى عليــه ‪........‬‬\n     ‫بحيــازة احلشــيش املخــدر املوصــوف بالدعــوى بقصــد التعاطــي ولكــون‬\n\n\n‫‪83‬‬\n\f‫هــذا اإلقــرار قــد صــدر مــن مكلفــن عاقلــن بالغــن وللقاعــدة الفقهيــة‬\n‫أن املــرء مؤاخــذ بإقــراره والقاعــدة إقــرار اإلنســان علــى نفســه مقبــول‬\n‫(املنثــور مــن القواعــد للزركشــي ج‪.188/1‬األشــباه والنظائــر للســيوطي‬\n‫ج‪ )465/1‬ودرر احلــكام ج‪ 79/1‬وبعــد االطــاع علــى محضــر القبــض‬\n‫وإفــادة املدعــى عليــه ‪........‬بــأن ‪........‬شــريك معــه يف الكميــة املضبوطــة‬\n‫وبعــد االطــاع علــى التقريــر الكيمــاوي الشــرعي وبعــد االطــاع‬\n‫علــى التعميــم رقــم ‪/13‬ت‪ 939/‬يف ‪1417/6/25‬ه ـ والتعميــم رقــم‬\n‫‪/13‬ت‪ 1625/‬يف ‪1421/8/26‬ه ـ واخلاصــة بتنظيــم عقوبــات الوافديــن‬\n‫بتخفيــف عقوبــة الســجن وزيــادة اجللــد لــذا فقــد قــررت مــا يلــي‪ :‬القســم‬\n‫األول‪ :‬مــا يخــص املدعــى عليــه األول ‪ :........‬أوالً‪ :‬ثبــت لــدي قيــام‬\n‫املدعــى عليــه بتعاطــي احلشــيش املخــدر وقــررت جلــده حــد املســكر‬\n‫ثمانــن جلــدة حــد ًا يف مــكان عــام‪ .‬ثاني ـاً‪ :‬ثبــت لــدي حيــازة املدعــى‬\n‫عليــه لقطعــة احلشــيش املخــدر املوصوفــة بالدعــوى لقصــد االســتعمال‬\n‫ـاء علــى الفقــرة األولــى‬ ‫الشــخصي وكان املتوجــه تعزيــره لقــاء ذلــك بنـ ً‬\n‫مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات ولكــن لكــون الكميــة‬\n‫ـاء‬\n‫املضبوطــة قليلــة ولعــدم وجــود ســوابق مخــدرات علــى املدعــى عليــه وبنـ ً‬\n‫علــى الفقــرة األولــى مــن املــادة(‪ )60‬مــن نظــام مكافحــة املخــدرات‬\n‫لــذا فقــد قــررت النــزول عــن أدنــى عقوبــة نــص عليهــا يف املــادة (‪)41‬‬\n‫وقــررت تعزيــر املدعــى عليــه بالســجن ملــدة أربعــة أشــهر محســوب ًا منهــا‬\n‫مــدة توقيفــه‪ .‬ثالث ـاً‪ :‬نظــر ًا لثبــوت قيــام املدعــى عليــه بتعاطــي احلشــيش‬\n‫املخــدر وحيــازة قطعــة احلشــيش املخــدر املوصوفــة بالدعــوى لقصــد‬\n‫االســتعمال الشــخصي وهــذه اجلرائــم منصــوص عليهــا يف املــادة الثالثــة‬\n‫مــن نظــام مكافحــة املخــدرات لــذا فقــد قــررت بنــاء علــى الفقــرة الثانيــة‬\n\n\n                                                                                      ‫‪84‬‬\n\f     ‫مــن املــادة (‪ )56‬مــن نفــس النظــام بإبعــاد املدعــى عليــه عــن اململكــة بعــد‬\n     ‫انتهــاء محكوميتــه وال يســمح لــه بدخولهــا إال مبــا تقضــي بــه أنظمــة‬\n     ‫احلــج والعمــرة‪ .‬القســم الثانــي‪ :‬مــا يخــص املدعــى عليــه ‪ :........‬أوالً‪ :‬ثبــت‬\n     ‫لــدي قيــام املدعــى عليــه بتعاطــي احلشــيش املخــدر وقــررت جلــده حــد‬\n     ‫املســكر ثمانــن جلــدة حــد ًا يف مــكان عــام‪ .‬ثانيــا‪ :‬نظــر ًا العتــراف‬\n     ‫املدعــى عليــه ‪........‬يف ملــف التحقيــق املرفــق بأنــه شــريك مــع املدعــى‬\n     ‫عليــه ‪........‬يف الكميــة املضبوطــة وكــذا إفــادة املدعــى عليــه ‪........‬لــذا‬\n     ‫فقــد ثبــت لــدي اشــتراك املدعــى عليــه بحيــازة قطعــة احلشــيش املخــدر‬\n     ‫املوصوفــة بالدعــوى لقصــد االســتعمال الشــخصي وكان املتوجــه‬\n     ‫ـاء علــى الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬‫تعزيــره لقــاء ذلــك بنـ ً‬\n     ‫مكافحــة املخــدرات ولكــن لكــون الكميــة املضبوطــة قليلــة ولعــدم‬\n     ‫ـاء علــى الفقــرة األولــى‬ ‫وجــود ســوابق مخــدرات علــى املدعــى عليــه وبنـ ً‬\n     ‫مــن املــادة(‪ )60‬مــن نظــام مكافحــة املخــدرات لــذا فقــد قــررت النــزول‬\n     ‫عــن أدنــى عقوبــة نــص عليهــا يف املــادة (‪ )41‬وقــررت تعزيــر املدعــى عليــه‬\n     ‫بالســجن ملــدة ثالثــة أشــهر محســوب ًا منهــا مــدة توقيفــه‪ .‬ثالث ـاً‪ :‬نظــر ًا‬\n     ‫لثبــوت قيــام املدعــى عليــه بتعاطــي احلشــيش املخــدر واالشــتراك يف‬\n     ‫حيــازة قطعــة احلشــيش املخــدر املوصوفــة بالدعــوى لقصــد االســتعمال‬\n     ‫الشــخصي وهــذه اجلرائــم منصــوص عليهــا يف املــادة الثالثــة مــن نظــام‬\n     ‫مكافحــة املخــدرات لــذا فقــد قــررت بنــاء علــى الفقــرة الثانيــة مــن‬\n     ‫املــادة (‪ )56‬مــن نفــس النظــام بإبعــاد املدعــى عليــه عــن اململكــة بعــد‬\n     ‫انتهــاء محكوميتــه وال يســمح لــه بدخولهــا إال مبــا تقضــي بــه أنظمــة‬\n     ‫احلــج والعمــرة ومبــا ســبق كلــه حكمــت وبعرضــه علــى املدعــى عليهمــا‬\n     ‫قــررا القناعــة باحلكــم كمــا قــرر املدعــي العــام معارضتــه واكتفــى‬\n\n\n‫‪85‬‬\n\f‫مبــا جــاء يف الئحــة الدعــوى عــن تقــدمي الئحــة اعتراضيــة وعليــه تكــون‬\n‫القضيــة منتهيــة وقــررت بعــث كامــل أورق املعامل ـ ــة إلــى محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية قالــه ممليــه الفقيــر إلــى عفــو ربــه ‪........‬‬\n‫القاضــي باحملكمــة اجلزئيــة باألحســاء وصلــى اهلل وســلم علــى ســيدنا‬\n                                            ‫محمــد حــرر يف ‪1434/02/20‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحن قضــاة الدائرة اجلزائية الثانية‬\n‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة لــدى‬\n‫احملكمــة برقــم ‪/34/567996‬ج‪ 2‬وتاريــخ ‪1434/03/04‬ه ـ الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم‬\n‫‪ 34/90856‬وتاريــخ ‪ 1434/02/30‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ..‬املســجل برقــم ‪ 3443176‬وتاريــخ‬\n‫‪1434/02/20‬ه ـ اخلــاص بدعــوى‪ .......‬املدعــي العــام ضــد كل مــن‬\n‫‪ ......../1‬مصــري اجلنســية و‪ ......./2‬مصــري اجلنســية يف قضيــة مخــدرات‬\n‫وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصبحــه‬\n                                                  ‫وســلم ‪ .‬حــرر ‪1434/03/11‬هــ‪.‬‬\n\n\n\n\n                                                                                      ‫‪86‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":78,"source_page_end":86,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0896536f9bdbf5ddb938f33de3c3cb17289eba0b38676569fcc3ed55ce2f5d0f","normalized_text_hash":"6646674bf73dd5ea5325fedd453ed0e2d404594647a7507edc0f8b5833b37be8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p78-3443176"},{"id":"4422eab2-2488-5ff2-bbff-89fe1e7be72e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واملنع من السفر .","document_number":"34197431","case_number":"3422362","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/24","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34197431:‬تاريخه‪1434/04/24 :‬هـ‬\n                           ‫رقم الدعوى‪3422362:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34222538‬تاريخه‪1434/05/26 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬حــد املســكر‬\n      ‫‪ -‬إقــرار‪ -‬إدانــة ‪ -‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬التعزيــر بالســجن‬\n                                                            ‫واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬جــاء يف مجمــوع الفتــاوى (‪« :)135/29‬والصحيــح أن احلشيشــة‬\n      ‫مســكرة كالشــراب‪ ..‬إلــخ»‪ .‬وجــاء فيــه (‪« :)142/29‬وفيهــا مــن املفاســد‬\n                                                      ‫مــا ليــس يف اخلمــر‪ ..‬إلــخ»‪.‬‬\n      ‫‪ -2‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة‬\n      ‫(‪ )1‬مــن املــادة (‪ )56‬والفقــرة (‪ )1‬مــن املــادة (‪ )60‬مــن نظــام مكافحــة‬\n                                                  ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش‬\n      ‫املخــدر بقصــد التعاطــي وتعاطــي احلشــيش املخــدر‪ ،‬واحلكــم عليــه‬\n      ‫بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة‪ ،‬حيــث إنــه مت تفتيشــه مــن قبــل رجــل األمــن فقــام‬\n      ‫برمــي قطعــة يشــتبه أن تكــون مــن احلشــيش املخــدر‪ ،‬أثبــت التقريــر‬\n      ‫الكيمــاوي الشــرعي إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‪،‬‬\n\n‫‪87‬‬\n\f‫كمــا أقــر املدعــى عليــه أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‪،‬‬\n‫مــن املقــرر شــرع ًا أن احلشيشــة مســكرة وأن متعاطيهــا يحــد منهــا‪،‬‬\n‫وحيــث إن املدعــى عليــه أبــدى النــدم وال يوجــد لــه ســوابق والكميــة‬\n‫احملــازة قليلــة‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإدانــة املدعــى‬\n‫عليــه بجميــع مانســب إليــه وقــررت ســجنه ملــدة شــهر ومنعــه مــن الســفر‬\n‫خــارج اململكــة ملــدة ســنتني وجلــده ثمانــن جلــدة دفعــة واحــدة حــد‬\n‫املســكر‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪،‬‬\n                   ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ .......‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n‫مــن هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34107360‬وتاريــخ ‪1434/1/13‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 3422362‬وتاريــخ ‪1434/1/13‬ه ـ‬\n‫افتتحــت اجللســة يف يــوم األربعــاء ‪1434/4/24‬ه ـ الســاعة التاســعة‬\n‫والنصــف وفيهــا قــدم املدعــي العــام دعــواه ونصهــا اآلتــي‪ :‬بصفتــي‬\n‫مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‬\n‫‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقم(‪).................‬حيــث‬\n‫إنــه بتاريــخ ‪1433/11/26‬ه ـ وأثنــاء قيــام الدوريــة بعملهــا كاملعتــاد أمام‬\n‫كبــري ‪ .......‬بالدمــام مت مالحظــة مركبتــن متوقفتــن علــى جانــب‬\n‫الطريــق إحداهمــا بقيــادة املدعــى عليــه وبتفتيشــهم قــام املدعــى عليــه‬\n‫برمــي قطعــة يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪)0,7‬‬\n\n                                                                                        ‫‪88‬‬\n\f     ‫ســبعة مــن العشــرة مــن اجلــرام وقــد أثبــت التقريــر الكيمــاوي الشــرعي‬\n     ‫رقــم ‪ .).......‬لعــام ‪1433‬ه ـ الصــادر مــن املركز اإلقليمي ملراقبة الســموم‬\n     ‫باملنطقــة الشــرقية إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‬\n     ‫وباســتجواب املدعى عليه أقر بحيازته للكمية املضبوطة من احلشــيش‬\n     ‫املخــدر وأنهــا تعــود لــه وغرضــه منهــا االســتخدام الشــخصي وأنــه حصــل‬\n     ‫علــى قطعــة احلشــيش مــن شــخص ال يعرفــه كمــا اعتــرف بأنــه يتعاطــى‬\n     ‫احلشــيش منــذ ســنة تقريبـ ًا وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى‬\n     ‫عليــه بحيــازة مــا وزنــه (‪ )0,7‬ســبعة مــن العشــرة مــن اجلــرام مــن احلشــيش‬\n     ‫املخــدر بقصــد التعاطــي وتعاطــي احلشــيش املخــدر وذلــك لألدلــة‬\n     ‫والقرائــن التاليــة‪ -1 :‬مــا جــاء يف إقــراره مبحضــر االســتجواب املنــوه عنه‬\n     ‫واملرفــق لفــه رقــم (‪ -2 )12-11‬مــا جــاء يف مبحضــر القبــض والتفتيــش‬\n     ‫املنــوه عنــه واملرفــق لفــه رقــم ( ‪ -3 ) 2‬مــا جــاء يف التقريــر الكيمائــي‬\n     ‫الشــرعي املرفــق علــى اللفــة رقــم (‪ )14‬وبالبحــث عــن ســوابقه لــم يعثــر‬\n     ‫ـرم‬\n     ‫لــه علــى ســوابق وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محـ ٌ‬\n     ‫ـب عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات مــا أســند إليــه وفقـ ًا للقفــرة‬\n                                                                                  ‫ومعاقـ ٌ‬\n     ‫الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة واحلكــم عليــه باآلتــي‪ -1 :‬عقوبــة الســجن وفقـ ًا للفقــرة (‪ )1‬مــن‬\n     ‫املــادة (‪ )41‬مــن النظــام املشــار إليــه ‪ -2‬منعــه مــن الســفر وفق ـ ًا للفقــرة‬\n     ‫(‪ )1‬مــن املــادة (‪ )56‬مــن ذات النظــام هكــذا ادعــى وبعــرض دعــوى‬\n     ‫ا مــا ذكــره املدعــي العــام‬  ‫املدعــي العــام علــى املدعــى عليــه أجــاب قائـ ً‬\n     ‫كلــه صحيــح فقــد قبــض علـ ّـي وبحوزتــي احلشــيش بقصــد التعاطــي وأنــا‬\n     ‫أتعاطــى احلشــيش املخــدر وال توجــد لــدي ســوابق وأنــا تائــب إلــى اهلل مــن‬\n     ‫هــذا الفعــل هكــذا أجــاب ثــم جــرى الرجــوع إلــى املعاملــة فوجــدت علــى‬\n\n\n‫‪89‬‬\n\f‫لفــة رقــم (‪ )11‬تقريــر كيمــاوي شــرعي رقــم ‪ ........‬املتضمــن احتــواء‬\n‫العينــة املضبوطــة علــى مــادة احلشــيش املخــدر كمــا وجــدت علــى لفــة‬\n‫رقــم (‪ )18‬كــرت بصمــات للمدعــى عليــه املتضمــن عــدم وجــود ســوابق‬\n‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه‬  ‫لــه فبنـ ً‬\n‫ـاء علــى‬\n        ‫وإقــراره بالدعــوى وهــو بكامــل أهليتــه املعتبــرة شــرع ًا وبنـ ً‬\n‫الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )56‬والفقــرة (‪ )1‬مــن املــادة (‪ )60‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ومبــا أن احلشــيش مســكر حيــث ذكــر‬\n‫شــيخ اإلســام ابــن تيميــة يف مجمــوع الفتــاوى مــا نصــه‪( :‬والصحيــح أن‬\n‫احلشيشــة مســكرة كالشــراب وأن آكلهــا يحــد منهــا فهــي خمــر )‬\n‫(ج‪/29‬ص‪ )135‬كمــا قــال‪( :‬وفيهــا مــن املفاســد مــا ليــس يف اخلمــر وإن‬\n‫كان يف اخلمــر مفســدة ليســت فيهــا وهــي احلــدة فهــي بالتحــرمي أولــى‬\n‫مــن اخلمــر ألن ضــرر آكل احلشيشــة علــى نفســه أشــد مــن ضــرر اخلمــر‬\n‫وضــرر شــارب اخلمــر علــى النــاس أشــد إال أنــه يف هــذه األزمــان لكثــرة‬\n‫أكل احلشيشــة صــار الضــرر الــذي منهــا علــى النــاس أعظــم مــن اخلمــر)‬\n‫مجمــوع الفتــاوى (ج‪/29‬ص‪ )142‬ونظــر ًا لعــدم وجــود ســوابق للمدعــى‬\n‫عليــه ومــا أبــداه مــن نــدم علــى هــذا الفعــل ونظــر ًا لقلــة الكميــة احملــازة‬\n‫لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة مــا وزنــه (‪ )0,7‬ســبعة‬\n‫مــن العشــرة مــن اجلــرام مــن احلشــيش املخــدر بقصــد التعاطــي كمــا‬\n‫ثبــت لــدي تعاطيــه للحشــيش املخــدر وقــررت معاقبتــه علــى ذلــك مبــا‬\n‫يلــي‪ :‬أوالً‪ :‬ســجنه ملــدة شــهر حتتســب منهــا مــدة إيقافــه‪ .‬ثاني ـاً‪ :‬منعــه‬\n‫مــن الســفر خــارج اململكــة ملــدة ســنتني تبــدأ بعــد انتهــاء فتــرة الســجن‬\n‫املقــررة بحقــه يف البنــد أوالً‪ .‬ثالثـاً‪ :‬جلــده ثمانــن جلــدة دفعــة واحــدة حــد‬\n\n\n                                                                                           ‫‪90‬‬\n\f     ‫املســكر ويكــون التنفيــذ يف مــكان عــام يحضــره جمــع مــن النــاس‬\n     ‫وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n     ‫القناعــة باحلكــم كمــا قــرر املدعــي العــام االعتــراض مكتفيـ ًا بالئحــة‬\n     ‫الدعــوى العامــة وأمــرت برفــع املعاملــة إلــى محكمــة االســتئناف وبــاهلل‬\n     ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/04/24‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪1434/06/07‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة احلاديــة عشــرة والنصــف وفيهــا وردتنــا املعاملــة مــن‬\n     ‫محكمــة االســتئناف باملنطقــة الشــرقية برقــم ‪ 34/1360311‬يف‬\n     ‫‪1434/06/06‬ه ـ وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة‬\n     ‫برقــم ‪ 34222538‬يف ‪1434/05/26‬ه ـ املتضمــن املصادقــة على احلكم‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم‪ .‬حــرر يف ‪1434/06/07‬ه ـ‬\n\n\n\n\n‫‪91‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":87,"source_page_end":91,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4e570bc156f17cd7cde98a0c56e4713f24ba40549121a3cda2cccc9bf15f8f80","normalized_text_hash":"770512b8333b1c39e7797a5dd459a64bc8d5f3dd2c11134d654c21bfa7449a26","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p87-34197431"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

